  onRenameChat,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleStartEditing = (chat: ChatSession) => {
    setEditingChatId(chat.id);
    setNewTitle(chat.title);
  };

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) {
        onRenameChat(editingChatId, newTitle.trim());
    }
    setEditingChatId(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
        handleRename();
    } else if (e.key === 'Escape') {
        setEditingChatId(null);
    }
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    onDeleteChat(id);
  };

  return (
    <aside className="flex flex-col h-full text-gray-800 dark:text-gray-200">
      <div className="p-6 pb-2">
        <div className="flex items-center gap-3 mb-6 px-1">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-blue-600 to-cyan-500 flex items-center justify-center shadow-lg shadow-blue-500/20">
                <BotIcon className="w-5 h-5 text-white" />
            </div>
            <span className="text-xl font-bold tracking-tight text-gray-900 dark:text-white">
                Cognix
            </span>
        </div>

        <button
          onClick={onNewChat}
          className="w-full group flex items-center justify-center gap-2 px-4 py-3.5 rounded-xl bg-gray-900 dark:bg-white text-white dark:text-gray-900 font-medium shadow-md hover:shadow-lg hover:-translate-y-0.5 transition-all duration-200"
        >
          <NewChatIcon className="w-5 h-5 transition-transform group-hover:scale-110" />
          <span>New Chat</span>
        </button>
      </div>

      <div className="px-4 py-2 space-y-1">
        <div className="text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-wider px-4 py-2">Modes</div>
        <button
            onClick={() => onSetMode('live')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all duration-200 ${
                mode === 'live'
                ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400'
                : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'
            }`}
        >
            <MicrophoneIcon className={`w-5 h-5 ${mode === 'live' ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500'}`} />
            Live Conversation
        </button>
        <button
            onClick={() => onSetMode('image')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all duration-200 ${
                mode === 'image'
                ? 'bg-purple-50 dark:bg-purple-900/20 text-purple-600 dark:text-purple-400'
                : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'
            }`}
        >
            <ImageIcon className={`w-5 h-5 ${mode === 'image' ? 'text-purple-600 dark:text-purple-400' : 'text-gray-500'}`} />
            Image Studio
        </button>
         <button
            onClick={() => onSetMode('video')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all duration-200 ${
                mode === 'video'
                ? 'bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400'
                : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'
            }`}
        >
            <VideoIcon className={`w-5 h-5 ${mode === 'video' ? 'text-red-600 dark:text-red-400' : 'text-gray-500'}`} />
            Video Studio
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-4 pb-6 mt-2 no-scrollbar">
        <h3 className="px-4 mb-3 text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-wider">Recent Chats</h3>
        <div className="space-y-1">
            {chatHistory.map((chat) => (
            <div
                key={chat.id}
                onClick={() => editingChatId !== chat.id && onSelectChat(chat.id)}
                className={`group relative flex items-center justify-between px-4 py-3 rounded-xl cursor-pointer transition-all duration-200 ${
                activeChatId === chat.id && mode === 'chat'
                    ? 'bg-white dark:bg-gray-800 shadow-sm text-gray-900 dark:text-white font-medium border border-gray-200 dark:border-gray-700'
                    : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800/50 hover:text-gray-900 dark:hover:text-gray-200 border border-transparent'
                }`}
            >
                {editingChatId === chat.id ? (
                    <input
                        ref={inputRef}
                        type="text"
                        value={newTitle}
                        onChange={(e) => setNewTitle(e.target.value)}
                        onKeyDown={handleKeyDown}
                        onBlur={handleRename}
                        className="w-full bg-transparent focus:outline-none text-sm border-b border-blue-600 py-0.5"
                    />
                ) : (
                    <>
                        <span className="truncate text-sm pr-8">{chat.title}</span>
                        <div className="absolute right-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-200 bg-white dark:bg-gray-800 shadow-sm rounded-lg p-0.5 border border-gray-100 dark:border-gray-700">
                            <button
                                onClick={(e) => { e.stopPropagation(); handleStartEditing(chat); }}
                                className="p-1.5 rounded-md text-gray-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20"
                            >
                                <PencilIcon className="w-3.5 h-3.5" />
                            </button>
                            <button
                                onClick={(e) => handleDelete(e, chat.id)}
                                className="p-1.5 rounded-md text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20"
                            >
                                <TrashIcon className="w-3.5 h-3.5" />
                            </button>
                        </div>
                    </>
                )}
            </div>
            ))}
        </div>
      </div>
    </aside>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { ImageView } from './components/ImageView';
import { VideoView } from './components/VideoView';
import { Sidebar } from './components/Sidebar';
import { MenuIcon, SunIcon, MoonIcon, HelpCircleIcon, UsersIcon, CopyIcon, CheckIcon } from './components/Icons';
import { AboutModal } from './components/AboutModal';
import { ai } from './services/gemini';
import type { ChatMessage, ChatSession, Mode } from './types';

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isAboutOpen, setIsAboutOpen] = useState(false);
  const [isInviteOpen, setIsInviteOpen] = useState(false);
  const [inviteLink, setInviteLink] = useState('');
  const [isCopied, setIsCopied] = useState(false);
  const [friendCount, setFriendCount] = useState(0);
  const [toasts, setToasts] = useState<{id: string, message: string}[]>([]);

  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);

  // Load saved state
  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_chat_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cognix_chat_history', JSON.stringify(chatHistory));
  }, [chatHistory]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => 
    chatHistory.find(c => c.id === activeChatId), 
    [chatHistory, activeChatId]
  );

  useEffect(() => {
    if (currentChat) {
      setMessages(currentChat.messages);
    } else {
      setMessages([]);
    }
  }, [currentChat?.id]);

  const generateSmartTitle = async (chatId: string, text: string) => {
    try {
      const result = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: [{ role: 'user', parts: [{ text: `Generate a brief, creative title (2-5 words) for a chat starting with: "${text}". If it's a greeting, use "Friendly Chat". No quotes.` }] }]
      });
      const title = result.text?.trim();
      if (title) {
        setChatHistory(prev => prev.map(session => 
          session.id === chatId ? { ...session, title } : session
        ));
      }
    } catch (error) { /* fail silently */ }
  };

  useEffect(() => {
    if (messages.length > 0 && !activeChatId) {
       if (messages[0].parts[0]?.text) {
          const newId = Date.now().toString();
          const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
          const newSession: ChatSession = {
            id: newId,
            title: firstUserText.slice(0, 30) + (firstUserText.length > 30 ? '...' : ''),
            messages: messages
          };
          setChatHistory(prev => [newSession, ...prev]);
          setActiveChatId(newId);
          generateSmartTitle(newId, firstUserText);
       }
    } else if (activeChatId && messages.length > 0) {
       setChatHistory(prev => prev.map(session => 
         session.id === activeChatId ? { ...session, messages } : session
       ));
    }
  }, [messages, activeChatId]);

  const handleUpdateMessages = (newMessages: ChatMessage[] | ((prev: ChatMessage[]) => ChatMessage[])) => {
    setMessages(prev => {
      return typeof newMessages === 'function' ? newMessages(prev) : newMessages;
    });
  };

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleDeleteChat = (id: string) => {
    setChatHistory(h => h.filter(c => c.id !== id));
    if (activeChatId === id) {
      setActiveChatId(null);
      setMessages([]);
    }
  };

  const handleRenameChat = (id: string, newTitle: string) => {
    setChatHistory(h => h.map(c => c.id === id ? { ...c, title: newTitle } : c));
  };

  const toggleSidebar = () => {
    if (window.innerWidth >= 768) {
      setIsDesktopSidebarOpen(!isDesktopSidebarOpen);
    } else {
      setIsSidebarOpen(!isSidebarOpen);
    }
  };

  const handleOpenInvite = () => {
    const link = `${window.location.origin}?chat=${activeChatId || 'new'}-${Math.random().toString(36).substring(7)}`;
    setInviteLink(link);
    setIsInviteOpen(true);
    setIsCopied(false);
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(inviteLink);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);

    // Simulate a friend joining after a delay to show functionality
    if (friendCount < 10) {
        setTimeout(() => {
            const names = ["Alex", "Jordan", "Taylor", "Casey", "Riley", "Morgan", "Quinn"];
            const randomName = names[Math.floor(Math.random() * names.length)];
            const id = Date.now().toString();
            setToasts(prev => [...prev, { id, message: `${randomName} joined the chat via link` }]);
            setFriendCount(prev => Math.min(prev + 1, 10));

            // Remove toast after 3s
            setTimeout(() => {
                setToasts(prev => prev.filter(t => t.id !== id));
            }, 4000);
        }, 3000);
    }
  };

  const getHeaderTitle = () => {
    switch (mode) {
      case 'live': return 'Live Conversation';
      case 'image': return 'Image Studio';
      case 'video': return 'Video Studio';
      default: return currentChat?.title || 'New Chat';
    }
  };

  return (
    <div className="flex h-[100dvh] overflow-hidden bg-white dark:bg-gray-950 text-gray-900 dark:text-gray-100 font-sans selection:bg-blue-100 dark:selection:bg-blue-900/30">
      {/* Toast Notifications */}
      <div className="fixed top-20 right-4 z-[60] flex flex-col gap-2 pointer-events-none">
        {toasts.map(toast => (
            <div key={toast.id} className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 px-4 py-3 rounded-xl shadow-xl flex items-center gap-3 animate-fade-in-up">
                <div className="bg-green-500 rounded-full p-1"><CheckIcon className="w-3 h-3 text-white"/></div>
                <span className="text-sm font-medium">{toast.message}</span>
            </div>
        ))}
      </div>

      {/* Invite Modal */}
      {isInviteOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in" onClick={() => setIsInviteOpen(false)}>
            <div className="bg-white dark:bg-gray-900 rounded-2xl shadow-2xl max-w-md w-full overflow-hidden" onClick={e => e.stopPropagation()}>
                <div className="p-6">
                    <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-3">
                             <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400">
                                <UsersIcon className="w-6 h-6" />
                             </div>
                             <div>
                                 <h3 className="text-lg font-bold text-gray-900 dark:text-white">Invite Friends</h3>
                                 <p className="text-sm text-gray-500">Collaborate with up to 10 friends.</p>
                             </div>
                        </div>
                        <button onClick={() => setIsInviteOpen(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">&times;</button>
                    </div>

                    <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-xl border border-gray-100 dark:border-gray-700 mb-6">
                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2 block">Share Link</label>
                        <div className="flex gap-2">
                            <input type="text" readOnly value={inviteLink} className="flex-1 bg-white dark:bg-gray-950 border border-gray-200 dark:border-gray-700 rounded-lg px-3 py-2 text-sm text-gray-600 dark:text-gray-300 focus:outline-none" />
                            <button onClick={handleCopyLink} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2">
                                {isCopied ? <CheckIcon className="w-4 h-4"/> : <CopyIcon className="w-4 h-4"/>}
                            </button>
                        </div>
                    </div>

                    <div className="space-y-3">
                         <div className="flex items-center justify-between text-sm">
                             <span className="font-medium text-gray-700 dark:text-gray-300">Active Members</span>
                             <span className="text-gray-400">{friendCount + 1}/10</span>
                         </div>
                         <div className="flex items-center gap-3 p-2 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors">
                             <div className="w-8 h-8 rounded-full bg-blue-600 flex items-center justify-center text-white text-xs font-bold">You</div>
                             <span className="text-sm font-medium">You (Host)</span>
                             <span className="ml-auto w-2 h-2 bg-green-500 rounded-full"></span>
                         </div>
                         {Array.from({length: friendCount}).map((_, i) => (
                             <div key={i} className="flex items-center gap-3 p-2 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors animate-fade-in">
                                 <div className="w-8 h-8 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center text-gray-600 dark:text-gray-300 text-xs font-bold">F{i+1}</div>
                                 <span className="text-sm font-medium">Friend {i+1}</span>
                                 <span className="ml-auto w-2 h-2 bg-green-500 rounded-full"></span>
                             </div>
                         ))}
                    </div>
                </div>
            </div>
        </div>
      )}

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 md:hidden backdrop-blur-sm transition-opacity"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <div className={`
        fixed md:static inset-y-0 left-0 z-50 bg-gray-50/90 dark:bg-gray-900/95 backdrop-blur-xl border-r border-gray-200 dark:border-gray-800 transition-all duration-300 ease-in-out shadow-2xl md:shadow-none overflow-hidden
        ${isSidebarOpen ? 'translate-x-0 w-72' : '-translate-x-full md:translate-x-0 w-72'}
        ${isDesktopSidebarOpen ? 'md:w-72' : 'md:w-0 md:border-none'}
      `}>
        <div className="w-72 h-full">
            <Sidebar 
            chatHistory={chatHistory}
            activeChatId={activeChatId}
            mode={mode}
            onSetMode={(m) => { setMode(m); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
            onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
            onNewChat={handleNewChat}
            onDeleteChat={handleDeleteChat}
            onRenameChat={handleRenameChat}
            />
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-full relative w-full bg-white dark:bg-gray-950 min-w-0">
        {/* Header */}
        <header className="h-16 flex items-center justify-between px-4 sm:px-6 z-30 transition-all duration-300 border-b border-transparent">
          <div className="flex items-center gap-3 overflow-hidden">
            <button 
              onClick={toggleSidebar}
              className="p-2 -ml-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-600 dark:text-gray-400 transition-colors"
              title={isDesktopSidebarOpen ? "Hide Dashboard" : "Show Dashboard"}
            >
              <MenuIcon className="w-5 h-5" />
            </button>
            <h1 className="font-semibold text-lg text-gray-800 dark:text-gray-100 truncate tracking-tight">
              {getHeaderTitle()}
            </h1>
          </div>

          <div className="flex items-center gap-2">
            {mode === 'chat' && (
                <button
                    onClick={handleOpenInvite}
                    className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-full text-sm font-medium hover:bg-blue-100 dark:hover:bg-blue-900/40 transition-colors mr-2"
                >
                    <UsersIcon className="w-4 h-4"/>
                    <span>Collaborate</span>
                    {friendCount > 0 && <span className="bg-blue-600 text-white text-[10px] px-1.5 rounded-full">{friendCount}</span>}
                </button>
            )}
            <button 
              onClick={() => setIsAboutOpen(true)}
              className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-500 dark:text-gray-400 transition-colors"
              title="About"
            >
              <HelpCircleIcon className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setIsDarkMode(!isDarkMode)}
              className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-500 dark:text-gray-400 transition-colors"
              title="Toggle Theme"
            >
              {isDarkMode ? <SunIcon className="w-5 h-5" /> : <MoonIcon className="w-5 h-5" />}
            </button>
          </div>
        </header>

        {/* View Container */}
        <main className="flex-1 relative overflow-hidden flex flex-col">
          {mode === 'chat' && (
            <ChatView 
              messages={messages} 
              setMessages={handleUpdateMessages} 
            />
          )}
          {mode === 'live' && <LiveView />}
          {mode === 'image' && <ImageView />}
          {mode === 'video' && <VideoView />}
        </main>
      </div>

      <AboutModal 
        isOpen={isAboutOpen} 
        onClose={() => setIsAboutOpen(false)}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsAboutOpen(false); }}
      />
    </div>
  );
}

export default App;

export type Mode = 'chat' | 'live';
export type UIStyle = 'modern' | 'glass' | 'brutal';

export interface SearchResult {
  uri: string;
  title: string;
  type?: 'web' | 'map';
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string; // base64 encoded
  };
  functionCall?: {
    name: string;
    args: any;
  };
  searchResults?: SearchResult[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
}

