import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, UIStyle } from '../types';
import { NewChatIcon, TrashIcon, PencilIcon, MicrophoneIcon, BotIcon, SettingsIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  onRenameChat: (id: string, newTitle: string) => void;
  onOpenSettings: () => void;
  uiStyle: UIStyle;
}

export const Sidebar: React.FC<SidebarProps> = ({
  chatHistory,
  activeChatId,
  mode,
  onSetMode,
  onSelectChat,
  onNewChat,
  onDeleteChat,
  onRenameChat,
  onOpenSettings,
  uiStyle,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleStartEditing = (chat: ChatSession) => {
    setEditingChatId(chat.id);
    setNewTitle(chat.title);
  };

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) onRenameChat(editingChatId, newTitle.trim());
    setEditingChatId(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleRename();
    else if (e.key === 'Escape') setEditingChatId(null);
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    onDeleteChat(id);
  };

  return (
    <aside className="flex flex-col h-full text-gray-800 dark:text-gray-200 relative z-10">
      <div className="p-6 pb-2">
        <div className="flex items-center gap-3 mb-6 px-1">
            <div className={`w-9 h-9 flex items-center justify-center transition-all duration-300
                 ${uiStyle === 'brutal' ? 'bg-blue-600 border border-black shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] rounded-none' 
                 : 'rounded-xl bg-gradient-to-tr from-blue-600 to-cyan-500 shadow-lg shadow-blue-500/20'}`}>
                <BotIcon className="w-5 h-5 text-white" />
            </div>
            <span className="text-xl font-bold tracking-tight text-gray-900 dark:text-white">Cognix</span>
        </div>

        <button
          onClick={onNewChat}
          className={`w-full group flex items-center justify-center gap-2 px-4 py-3.5 font-medium transition-all duration-200
            ${uiStyle === 'brutal' 
                ? 'bg-black text-white dark:bg-white dark:text-black rounded-none border border-transparent shadow-[4px_4px_0px_0px_rgba(100,100,100,1)] hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-[2px_2px_0px_0px_rgba(100,100,100,1)]'
                : 'rounded-xl bg-gray-900 dark:bg-white text-white dark:text-gray-900 shadow-md hover:shadow-lg hover:-translate-y-0.5'}`}
        >
          <NewChatIcon className="w-5 h-5 transition-transform group-hover:scale-110" />
          <span>New Chat</span>
        </button>
      </div>

      <div className="px-4 py-2 space-y-1">
        <button
            onClick={() => onSetMode('live')}
            className={`w-full flex items-center gap-3 px-4 py-3 text-sm font-medium transition-all duration-200
                ${uiStyle === 'brutal' ? 'rounded-none border border-transparent hover:border-black hover:bg-blue-50' : 'rounded-xl'}
                ${mode === 'live'
                ? uiStyle === 'brutal' ? 'bg-blue-100 border-black font-bold' : 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400'
                : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'
            }`}
        >
            <MicrophoneIcon className={`w-5 h-5 ${mode === 'live' ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500'}`} />
            Live Conversation
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-4 pb-6 mt-2 no-scrollbar">
        <h3 className="px-4 mb-3 text-xs font-bold text-gray-400 dark:text-gray-500 uppercase tracking-wider">Recent Chats</h3>
        <div className="space-y-1">
            {chatHistory.map((chat) => (
            <div
                key={chat.id}
                onClick={() => editingChatId !== chat.id && onSelectChat(chat.id)}
                className={`group relative flex items-center justify-between px-4 py-3 cursor-pointer transition-all duration-200
                ${uiStyle === 'brutal' ? 'rounded-none border-b border-gray-200 dark:border-gray-800 hover:bg-gray-50' : 'rounded-xl'}
                ${activeChatId === chat.id && mode === 'chat'
                    ? uiStyle === 'brutal' ? 'bg-gray-100 dark:bg-gray-800 font-bold border-l-4 border-l-blue-600' : 'bg-white dark:bg-gray-800 shadow-sm text-gray-900 dark:text-white font-medium border border-gray-200 dark:border-gray-700'
                    : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800/50 hover:text-gray-900 dark:hover:text-gray-200 border border-transparent'
                }`}
            >
                {editingChatId === chat.id ? (
                    <input
                        ref={inputRef}
                        type="text"
                        value={newTitle}
                        onChange={(e) => setNewTitle(e.target.value)}
                        onKeyDown={handleKeyDown}
                        onBlur={handleRename}
                        className="w-full bg-transparent focus:outline-none text-sm border-b border-blue-600 py-0.5"
