import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ai } from '../services/gemini';
import { MicrophoneIcon, StopIcon, BotIcon } from './Icons';
import type { LiveServerMessage, Blob } from '@google/genai';
import { Modality } from '@google/genai';

function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

function decode(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
        const channelData = buffer.getChannelData(channel);
        for (let i = 0; i < frameCount; i++) {
            channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
        }
    }
    return buffer;
}

interface TranscriptEntry {
    speaker: 'user' | 'model';
    text: string;
}

export const LiveView: React.FC = () => {
    const [isRecording, setIsRecording] = useState(false);
    const [transcripts, setTranscripts] = useState<TranscriptEntry[]>([]);

    const sessionPromiseRef = useRef<ReturnType<typeof ai.live.connect> | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const outputNodeRef = useRef<GainNode | null>(null);
    const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
    const mediaStreamSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
    const outputSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
    const nextStartTimeRef = useRef(0);
    const currentInputTranscriptionRef = useRef('');
    const currentOutputTranscriptionRef = useRef('');
    const transcriptContainerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (transcriptContainerRef.current) transcriptContainerRef.current.scrollTop = transcriptContainerRef.current.scrollHeight;
    }, [transcripts]);

    const stopSession = useCallback(async () => {
        if (sessionPromiseRef.current) {
            try {
                const session = await sessionPromiseRef.current;
                session.close();
            } catch (e) { console.error("Error closing session", e); }
            sessionPromiseRef.current = null;
        }
        streamRef.current?.getTracks().forEach(track => track.stop());
        streamRef.current = null;
        scriptProcessorRef.current?.disconnect();
        scriptProcessorRef.current = null;
        mediaStreamSourceRef.current?.disconnect();
        mediaStreamSourceRef.current = null;
        if (inputAudioContextRef.current?.state !== 'closed') await inputAudioContextRef.current?.close();
        if (outputAudioContextRef.current?.state !== 'closed') await outputAudioContextRef.current?.close();
        outputNodeRef.current = null;
        outputSourcesRef.current.forEach(source => source.stop());
        outputSourcesRef.current.clear();
        setIsRecording(false);
    }, []);

    const startSession = useCallback(async () => {
        setIsRecording(true);
        setTranscripts([]);
        currentInputTranscriptionRef.current = '';
        currentOutputTranscriptionRef.current = '';

        const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
        const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        if (inputCtx.state === 'suspended') await inputCtx.resume();
        if (outputCtx.state === 'suspended') await outputCtx.resume();

        const outputNode = outputCtx.createGain();
        outputNode.connect(outputCtx.destination);
        inputAudioContextRef.current = inputCtx;
        outputAudioContextRef.current = outputCtx;
        outputNodeRef.current = outputNode;
        nextStartTimeRef.current = 0;

        const createBlob = (data: Float32Array): Blob => {
            const l = data.length;
            const int16 = new Int16Array(l);
            for (let i = 0; i < l; i++) { int16[i] = data[i] * 32768; }
            return { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
        };

        sessionPromiseRef.current = ai.live.connect({
            model: 'gemini-2.5-flash-native-audio-preview-09-2025',
            callbacks: {
                onopen: async () => {
                    try {
                        streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
                        mediaStreamSourceRef.current = inputAudioContextRef.current!.createMediaStreamSource(streamRef.current);
                        scriptProcessorRef.current = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
                        scriptProcessorRef.current.onaudioprocess = (e) => {
                            sessionPromiseRef.current?.then((session) => {
                                session.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
                            });
                        };
                        mediaStreamSourceRef.current.connect(scriptProcessorRef.current);
                        scriptProcessorRef.current.connect(inputAudioContextRef.current!.destination);
                    } catch (err) { stopSession(); }
                },
                onmessage: async (message: LiveServerMessage) => {
                    try {
                        const currentOutputCtx = outputAudioContextRef.current!;
                        if (!currentOutputCtx || currentOutputCtx.state === 'closed') return;

                        const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (base64Audio) {
                            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, currentOutputCtx.currentTime);
                            const audioBuffer = await decodeAudioData(decode(base64Audio), currentOutputCtx, 24000, 1);
                            const source = currentOutputCtx.createBufferSource();
                            source.buffer = audioBuffer;
                            source.connect(outputNodeRef.current!);
                            source.addEventListener('ended', () => { outputSourcesRef.current.delete(source) });
                            source.start(nextStartTimeRef.current);
                            nextStartTimeRef.current += audioBuffer.duration;
                            outputSourcesRef.current.add(source);
                        }

                        if (message.serverContent?.interrupted) {
                            outputSourcesRef.current.forEach(source => source.stop());
                            outputSourcesRef.current.clear();
                            nextStartTimeRef.current = 0;
                        }

                        if (message.serverContent?.inputTranscription) {
                            currentInputTranscriptionRef.current += message.serverContent.inputTranscription.text;
                            setTranscripts(prev => {
                                const last = prev[prev.length - 1];
                                if (last?.speaker === 'user') return [...prev.slice(0, -1), { ...last, text: currentInputTranscriptionRef.current }];
                                return [...prev, { speaker: 'user', text: currentInputTranscriptionRef.current }];
                            });
                        } else if (message.serverContent?.outputTranscription) {
                            currentOutputTranscriptionRef.current += message.serverContent.outputTranscription.text;
                            setTranscripts(prev => {
                                const last = prev[prev.length - 1];
                                if (last?.speaker === 'model') return [...prev.slice(0, -1), { ...last, text: currentOutputTranscriptionRef.current }];
                                return [...prev, { speaker: 'model', text: currentOutputTranscriptionRef.current }];
                            });
                        }

                        if (message.serverContent?.turnComplete) {
                            currentInputTranscriptionRef.current = '';
                            currentOutputTranscriptionRef.current = '';
                        }
                    } catch (error) { stopSession(); }
                },
                onerror: () => stopSession(),
                onclose: () => setIsRecording(false),
            },
            config: {
                responseModalities: [Modality.AUDIO],
                inputAudioTranscription: {},
                outputAudioTranscription: {},
                systemInstruction: "You are Cognix AI. Speak naturally and concisely.",
            },
        });
    }, [stopSession]);

    const handleToggleRecording = () => isRecording ? stopSession() : startSession();
    useEffect(() => { return () => { stopSession(); }; }, [stopSession]);

    return (
        <div className="flex flex-col h-full items-center justify-center p-4 relative overflow-hidden">
            <div className={`absolute top-1/4 left-1/2 -translate-x-1/2 text-center transition-all duration-500 z-10 ${isRecording ? 'opacity-0 -translate-y-8' : 'opacity-100 translate-y-0'}`}>
                <div className="w-16 h-16 mx-auto mb-6 rounded-full bg-blue-600 flex items-center justify-center shadow-lg animate-pulse">
                     <MicrophoneIcon className="w-8 h-8 text-white" />
                </div>
                <h2 className="text-2xl font-semibold text-gray-800 dark:text-white mb-2">Live Mode</h2>
                <p className="mt-2 max-w-md text-gray-500 dark:text-gray-400 text-base">Talk to Cognix naturally in real-time.</p>
                <p className="mt-4 text-xs text-gray-400">Created by Shashwat Ranjan Jha</p>
            </div>

            <div ref={transcriptContainerRef} className={`w-full max-w-3xl h-full pt-4 pb-40 overflow-y-auto space-y-4 transition-opacity duration-500 z-10 ${isRecording ? 'opacity-100' : 'opacity-0'}`}>
                {transcripts.map((t, i) => (
                    <div key={i} className={`flex items-end gap-2 animate-fade-in-up ${t.speaker === 'user' ? 'justify-end' : 'justify-start'}`}>
                        {t.speaker === 'model' && <div className="w-8 h-8 rounded-full bg-black dark:bg-white flex items-center justify-center"><BotIcon className="w-4 h-4 text-white dark:text-black"/></div>}
                        <div className={`px-5 py-3 rounded-lg max-w-lg text-base ${t.speaker === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-100'}`}>
                            {t.text}
                        </div>
                    </div>
                ))}
            </div>

            <div className={`absolute bottom-0 left-0 right-0 h-48 flex justify-center items-end pb-10 gap-1 transition-opacity duration-500 ${isRecording ? 'opacity-100' : 'opacity-0'}`}>
                {Array.from({ length: 30 }).map((_, i) => (
                    <div key={i} className="w-1.5 bg-blue-600 rounded-full" style={{ height: `${Math.random() * 50 + 10}%`, animation: `wave 1s ease-in-out ${i * 0.05}s infinite alternate` }}></div>
                ))}
            </div>

            <button 
                onClick={handleToggleRecording} 
                className={`group absolute z-20 flex items-center justify-center rounded-full shadow-xl transition-all duration-500 ease-out
                    ${isRecording ? 'bottom-10 w-16 h-16 bg-red-600 hover:bg-red-700 rotate-0' : 'top-1/2 -translate-y-1/2 w-24 h-24 bg-blue-600 hover:bg-blue-700'}`}
            >
                {isRecording ? <StopIcon className="w-6 h-6 text-white" /> : <MicrophoneIcon className="w-8 h-8 text-white" />}
            </button>
            <style>{`@keyframes wave { 0% { transform: scaleY(0.2); } 100% { transform: scaleY(1); } }`}</style>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { MenuIcon, UsersIcon, CopyIcon, CheckIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import { ai } from './services/gemini';
import type { ChatMessage, ChatSession, Mode, UIStyle } from './types';

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Invite/Collab State
  const [isInviteOpen, setIsInviteOpen] = useState(false);
  const [inviteLink, setInviteLink] = useState('');
  const [isCopied, setIsCopied] = useState(false);
  const [friendCount, setFriendCount] = useState(0);
  const [toasts, setToasts] = useState<{id: string, message: string}[]>([]);

  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);

  // Load state
  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_chat_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }

    const savedStyle = localStorage.getItem('cognix_style') as UIStyle;
    if (savedStyle) setUiStyle(savedStyle);
  }, []);

  useEffect(() => localStorage.setItem('cognix_chat_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('cognix_style', uiStyle), [uiStyle]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  useEffect(() => {
    if (messages.length > 0 && !activeChatId) {
       if (messages[0].parts[0]?.text) {
          const newId = Date.now().toString();
          const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
          const newSession: ChatSession = {
            id: newId,
            title: firstUserText.slice(0, 30) + (firstUserText.length > 30 ? '...' : ''),
            messages: messages
          };
          setChatHistory(prev => [newSession, ...prev]);
          setActiveChatId(newId);
       }
    } else if (activeChatId && messages.length > 0) {
       setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
    }
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleOpenInvite = () => {
    const link = `${window.location.origin}?chat=${activeChatId || 'new'}-${Math.random().toString(36).substring(7)}`;
    setInviteLink(link);
    setIsInviteOpen(true);
    setIsCopied(false);
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(inviteLink);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
    if (friendCount < 10) {
        setTimeout(() => {
            const names = ["Alex", "Jordan", "Taylor", "Casey", "Riley"];
            const randomName = names[Math.floor(Math.random() * names.length)];
            const id = Date.now().toString();
            setToasts(prev => [...prev, { id, message: `${randomName} joined` }]);
            setFriendCount(prev => Math.min(prev + 1, 10));
            setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
        }, 3000);
    }
  };

  // Styles wrapper class
  const mainWrapperClass = useMemo(() => {
      switch(uiStyle) {
          case 'glass': return "bg-[url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2564&auto=format&fit=crop')] bg-cover bg-center";
          case 'brutal': return "bg-white dark:bg-gray-900";
          default: return "bg-white dark:bg-gray-950";
      }
  }, [uiStyle]);

  return (
    <div className={`flex h-[100dvh] overflow-hidden text-gray-900 dark:text-gray-100 font-sans selection:bg-blue-100 dark:selection:bg-blue-900/30 transition-all duration-300 ${mainWrapperClass}`}>
      {/* Toast Notifications */}
      <div className="fixed top-20 right-4 z-[70] flex flex-col gap-2 pointer-events-none">
        {toasts.map(toast => (
            <div key={toast.id} className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 px-4 py-3 rounded-xl shadow-xl flex items-center gap-3 animate-fade-in-up">
                <div className="bg-green-500 rounded-full p-1"><CheckIcon className="w-3 h-3 text-white"/></div>
                <span className="text-sm font-medium">{toast.message}</span>
            </div>
        ))}
      </div>

      {/* Invite Modal */}
      {isInviteOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in" onClick={() => setIsInviteOpen(false)}>
            <div className={`bg-white dark:bg-gray-900 rounded-2xl shadow-2xl max-w-md w-full overflow-hidden ${uiStyle === 'brutal' ? 'rounded-none border-2 border-black' : ''}`} onClick={e => e.stopPropagation()}>
                <div className="p-6">
                    <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-3">
                             <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400">
                                <UsersIcon className="w-6 h-6" />
                             </div>
                             <div>
                                 <h3 className="text-lg font-bold">Invite Friends</h3>
                                 <p className="text-sm text-gray-500">Collaborate with up to 10 friends.</p>
                             </div>
                        </div>
                        <button onClick={() => setIsInviteOpen(false)} className="text-gray-400 hover:text-gray-600">&times;</button>
                    </div>

                    <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-xl border border-gray-100 dark:border-gray-700 mb-6">
                        <div className="flex gap-2">
                            <input type="text" readOnly value={inviteLink} className="flex-1 bg-white dark:bg-gray-950 border border-gray-200 dark:border-gray-700 rounded-lg px-3 py-2 text-sm text-gray-600 dark:text-gray-300 focus:outline-none" />
                            <button onClick={handleCopyLink} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2">
                                {isCopied ? <CheckIcon className="w-4 h-4"/> : <CopyIcon className="w-4 h-4"/>}
                            </button>
                        </div>
                    </div>

                    <div className="space-y-3">
                         <div className="flex items-center justify-between text-sm">
                             <span className="font-medium text-gray-700 dark:text-gray-300">Active Members</span>
                             <span className="text-gray-400">{friendCount + 1}/10</span>
                         </div>
                         <div className="flex items-center gap-3 p-2 rounded-lg bg-gray-50 dark:bg-gray-800/50">
                             <div className="w-8 h-8 rounded-full bg-blue-600 flex items-center justify-center text-white text-xs font-bold">You</div>
                             <span className="text-sm font-medium">You (Host)</span>
                             <span className="ml-auto w-2 h-2 bg-green-500 rounded-full"></span>
                         </div>
                         {Array.from({length: friendCount}).map((_, i) => (
                             <div key={i} className="flex items-center gap-3 p-2 rounded-lg animate-fade-in">
                                 <div className="w-8 h-8 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center text-gray-600 dark:text-gray-300 text-xs font-bold">F{i+1}</div>
                                 <span className="text-sm font-medium">Friend {i+1}</span>
                                 <span className="ml-auto w-2 h-2 bg-green-500 rounded-full"></span>
                             </div>
                         ))}
                    </div>
                </div>
            </div>
        </div>
      )}

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-40 md:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />}

      {/* Sidebar */}
      <div className={`
        fixed md:static inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out overflow-hidden h-full flex flex-col
        ${isSidebarOpen ? 'translate-x-0 w-72' : '-translate-x-full md:translate-x-0 w-72'}
        ${isDesktopSidebarOpen ? 'md:w-72' : 'md:w-0'}
        ${uiStyle === 'glass' ? 'bg-white/70 dark:bg-gray-900/70 backdrop-blur-xl border-r border-white/20' : ''}
        ${uiStyle === 'brutal' ? 'bg-white dark:bg-gray-900 border-r-2 border-black' : ''}
        ${uiStyle === 'modern' ? 'bg-gray-50/90 dark:bg-gray-900/95 backdrop-blur-xl border-r border-gray-200 dark:border-gray-800' : ''}
      `}>
         <Sidebar 
            chatHistory={chatHistory}
            activeChatId={activeChatId}
            mode={mode}
            onSetMode={(m) => { setMode(m); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
            onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
            onNewChat={handleNewChat}
            onDeleteChat={(id) => {
                setChatHistory(h => h.filter(c => c.id !== id));
                if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
            }}
            onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
            onOpenSettings={() => setIsSettingsOpen(true)}
            uiStyle={uiStyle}
         />
      </div>

      {/* Main Content */}
      <div className={`flex-1 flex flex-col h-full relative w-full min-w-0 transition-colors duration-300 
          ${uiStyle === 'glass' ? 'bg-white/30 dark:bg-black/40 backdrop-blur-lg' : ''}`}>
        {/* Header */}
        <header className="h-16 flex items-center justify-between px-4 sm:px-6 z-30 shrink-0">
          <div className="flex items-center gap-3 overflow-hidden">
            <button 
              onClick={() => window.innerWidth >= 768 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 -ml-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 text-gray-600 dark:text-gray-400 transition-colors"
            >
              <MenuIcon className="w-5 h-5" />
            </button>
            <h1 className="font-semibold text-lg text-gray-800 dark:text-gray-100 truncate tracking-tight">
              {mode === 'live' ? 'Live Conversation' : (currentChat?.title || 'New Chat')}
            </h1>
          </div>

          <div className="flex items-center gap-2">
            {mode === 'chat' && (
                <button
                    onClick={handleOpenInvite}
                    className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-colors mr-2
                        ${uiStyle === 'brutal' ? 'bg-white border border-black text-black hover:bg-blue-50' 
                        : 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 hover:bg-blue-100 dark:hover:bg-blue-900/40'}`}
                >
                    <UsersIcon className="w-4 h-4"/>
                    <span>Collaborate</span>
                    {friendCount > 0 && <span className="bg-blue-600 text-white text-[10px] px-1.5 rounded-full">{friendCount}</span>}
                </button>
            )}
          </div>
        </header>

        {/* View Container */}
        <main className="flex-1 relative overflow-hidden flex flex-col">
          {mode === 'chat' && (
            <ChatView 
              messages={messages} 
              setMessages={val => {
                  if(typeof val === 'function') setMessages(prev => val(prev));
                  else setMessages(val);
              }}
              uiStyle={uiStyle}
            />
          )}
          {mode === 'live' && <LiveView />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle}
        setUiStyle={setUiStyle}
        isDarkMode={isDarkMode}
        setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
      />
    </div>
  );
}

export default App;

