// Theme Definitions
const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', text: 'text-blue-600', textDark: 'text-blue-400', bgSoft: 'bg-blue-50', darkBgSoft: 'dark:bg-blue-900/20', border: 'border-blue-600', ring: 'focus:ring-blue-600', gradient: 'bg-gradient-to-tr from-blue-600 to-cyan-500' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-tr from-violet-600 to-fuchsia-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-tr from-emerald-600 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-tr from-rose-600 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-tr from-amber-600 to-orange-500' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [fontSize, setFontSize] = useState<FontSize>('normal');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Invite/Collab State
  const [isInviteOpen, setIsInviteOpen] = useState(false);
  const [inviteLink, setInviteLink] = useState('');
  const [isCopied, setIsCopied] = useState(false);
  const [friendCount, setFriendCount] = useState(0);
  const [toasts, setToasts] = useState<{id: string, message: string}[]>([]);

  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);

  // Load state
  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_chat_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }

    const savedStyle = localStorage.getItem('cognix_style') as UIStyle;
    if (savedStyle) setUiStyle(savedStyle);

    const savedAccent = localStorage.getItem('cognix_accent') as AccentColor;
    if (savedAccent) setAccentColor(savedAccent);

    const savedFont = localStorage.getItem('cognix_font') as FontSize;
    if (savedFont) setFontSize(savedFont);
  }, []);

  useEffect(() => localStorage.setItem('cognix_chat_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('cognix_style', uiStyle), [uiStyle]);
  useEffect(() => localStorage.setItem('cognix_accent', accentColor), [accentColor]);
  useEffect(() => localStorage.setItem('cognix_font', fontSize), [fontSize]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  useEffect(() => {
    if (messages.length > 0 && !activeChatId) {
       if (messages[0].parts[0]?.text) {
          const newId = Date.now().toString();
          const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
          const newSession: ChatSession = {
            id: newId,
            title: firstUserText.slice(0, 30) + (firstUserText.length > 30 ? '...' : ''),
            messages: messages
          };
          setChatHistory(prev => [newSession, ...prev]);
          setActiveChatId(newId);
       }
    } else if (activeChatId && messages.length > 0) {
       setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
    }
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleOpenInvite = () => {
    const link = `${window.location.origin}?chat=${activeChatId || 'new'}-${Math.random().toString(36).substring(7)}`;
    setInviteLink(link);
    setIsInviteOpen(true);
    setIsCopied(false);
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(inviteLink);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
    if (friendCount < 10) {
        setTimeout(() => {
            const names = ["Alex", "Jordan", "Taylor", "Casey", "Riley"];
            const randomName = names[Math.floor(Math.random() * names.length)];
            const id = Date.now().toString();
            setToasts(prev => [...prev, { id, message: `${randomName} joined` }]);
            setFriendCount(prev => Math.min(prev + 1, 10));
            setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
        }, 3000);
    }
  };

  // Styles wrapper class
  const mainWrapperClass = useMemo(() => {
      switch(uiStyle) {
          case 'glass': return "bg-[url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2564&auto=format&fit=crop')] bg-cover bg-center";
          case 'brutal': return "bg-white dark:bg-gray-900";
          case 'minimal': return "bg-gray-50 dark:bg-gray-950";
          default: return "bg-white dark:bg-gray-950";
      }
  }, [uiStyle]);

  return (
    <div className={`flex h-[100dvh] overflow-hidden text-gray-900 dark:text-gray-100 font-sans selection:bg-${accentColor}-100 dark:selection:bg-${accentColor}-900/30 transition-all duration-300 ${mainWrapperClass}`}>
      {/* Toast Notifications */}
      <div className="fixed top-20 right-4 z-[70] flex flex-col gap-2 pointer-events-none">
        {toasts.map(toast => (
            <div key={toast.id} className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 px-4 py-3 rounded-xl shadow-xl flex items-center gap-3 animate-fade-in-up">
                <div className="bg-green-500 rounded-full p-1"><CheckIcon className="w-3 h-3 text-white"/></div>
                <span className="text-sm font-medium">{toast.message}</span>
            </div>
        ))}
      </div>

      {/* Invite Modal */}
      {isInviteOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in" onClick={() => setIsInviteOpen(false)}>
            <div className={`bg-white dark:bg-gray-900 rounded-2xl shadow-2xl max-w-md w-full overflow-hidden ${uiStyle === 'brutal' ? 'rounded-none border-2 border-black' : ''}`} onClick={e => e.stopPropagation()}>
                <div className="p-6">
                    <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-3">
                             <div className={`p-2 rounded-lg ${activeTheme.bgSoft} ${activeTheme.text}`}>
                                <UsersIcon className="w-6 h-6" />
                             </div>
                             <div>
                                 <h3 className="text-lg font-bold">Invite Friends</h3>
                                 <p className="text-sm text-gray-500">Collaborate with up to 10 friends.</p>
                             </div>
                        </div>
                        <button onClick={() => setIsInviteOpen(false)} className="text-gray-400 hover:text-gray-600">&times;</button>
                    </div>

                    <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-xl border border-gray-100 dark:border-gray-700 mb-6">
                        <div className="flex gap-2">
                            <input type="text" readOnly value={inviteLink} className="flex-1 bg-white dark:bg-gray-950 border border-gray-200 dark:border-gray-700 rounded-lg px-3 py-2 text-sm text-gray-600 dark:text-gray-300 focus:outline-none" />
                            <button onClick={handleCopyLink} className={`${activeTheme.primary} ${activeTheme.primaryHover} text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2`}>
                                {isCopied ? <CheckIcon className="w-4 h-4"/> : <CopyIcon className="w-4 h-4"/>}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      )}

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-40 md:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />}

      {/* Sidebar */}
      <div className={`
        fixed md:static inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out overflow-hidden h-full flex flex-col
        ${isSidebarOpen ? 'translate-x-0 w-72' : '-translate-x-full md:translate-x-0 w-72'}
        ${isDesktopSidebarOpen ? 'md:w-72' : 'md:w-0'}
        ${uiStyle === 'glass' ? 'bg-white/70 dark:bg-gray-900/70 backdrop-blur-xl border-r border-white/20' : ''}
        ${uiStyle === 'brutal' ? 'bg-white dark:bg-gray-900 border-r-2 border-black' : ''}
        ${uiStyle === 'minimal' ? 'bg-white/80 dark:bg-black/80 backdrop-blur-lg border-r border-gray-100 dark:border-gray-800' : ''}
        ${uiStyle === 'modern' ? 'bg-gray-50/90 dark:bg-gray-900/95 backdrop-blur-xl border-r border-gray-200 dark:border-gray-800' : ''}
      `}>
         <Sidebar 
            chatHistory={chatHistory}
            activeChatId={activeChatId}
            mode={mode}
            onSetMode={(m) => { setMode(m); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
            onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
            onNewChat={handleNewChat}
            onDeleteChat={(id) => {
                setChatHistory(h => h.filter(c => c.id !== id));
                if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
            }}
            onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
            onOpenSettings={() => setIsSettingsOpen(true)}
            uiStyle={uiStyle}
            theme={activeTheme}
         />
      </div>

      {/* Main Content */}
      <div className={`flex-1 flex flex-col h-full relative w-full min-w-0 transition-colors duration-300 
          ${uiStyle === 'glass' ? 'bg-white/30 dark:bg-black/40 backdrop-blur-lg' : ''}`}>
        {/* Header */}
        <header className={`h-16 flex items-center justify-between px-4 sm:px-6 z-30 shrink-0 sticky top-0
            ${uiStyle === 'minimal' || uiStyle === 'modern' ? 'backdrop-blur-md bg-white/50 dark:bg-black/20' : ''}
        `}>
          <div className="flex items-center gap-3 overflow-hidden">
            <button 
              onClick={() => window.innerWidth >= 768 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 -ml-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 text-gray-600 dark:text-gray-400 transition-colors"
            >
              <MenuIcon className="w-5 h-5" />
            </button>
            <h1 className="font-semibold text-lg text-gray-800 dark:text-gray-100 truncate tracking-tight">
              {mode === 'live' ? 'Live Conversation' : (currentChat?.title || 'New Chat')}
            </h1>
          </div>

          <div className="flex items-center gap-2">
            {mode === 'chat' && (
                <button
                    onClick={handleOpenInvite}
                    className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-colors mr-2
                        ${uiStyle === 'brutal' ? 'bg-white border border-black text-black hover:bg-gray-50' 
                        : `${activeTheme.bgSoft} ${activeTheme.text} hover:opacity-80`}`}
                >
                    <UsersIcon className="w-4 h-4"/>
                    <span>Collaborate</span>
                    {friendCount > 0 && <span className={`${activeTheme.primary} text-white text-[10px] px-1.5 rounded-full`}>{friendCount}</span>}
                </button>
            )}
          </div>
        </header>

        {/* View Container */}
        <main className="flex-1 relative overflow-hidden flex flex-col">
          {mode === 'chat' && (
            <ChatView 
              messages={messages} 
              setMessages={val => {
                  if(typeof val === 'function') setMessages(prev => val(prev));
                  else setMessages(val);
              }}
              uiStyle={uiStyle}
              theme={activeTheme}
              fontSize={fontSize}
            />
          )}
          {mode === 'live' && <LiveView theme={activeTheme} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle}
        setUiStyle={setUiStyle}
        accentColor={accentColor}
        setAccentColor={setAccentColor}
        fontSize={fontSize}
        setFontSize={setFontSize}
        isDarkMode={isDarkMode}
        setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
      />
    </div>
  );
}

export default App;

export type Mode = 'chat' | 'live';
export type UIStyle = 'modern' | 'glass' | 'brutal' | 'retro';
export type AccentColor = 'blue' | 'violet' | 'emerald' | 'rose' | 'amber';
export type FontSize = 'small' | 'normal' | 'large';

export interface ThemeColors {
    primary: string;
    primaryHover: string;
    text: string;
    textDark: string;
    bgSoft: string;
    darkBgSoft: string;
    border: string;
    ring: string;
    gradient: string;
}

export interface SearchResult {
  uri: string;
  title: string;
  type?: 'web' | 'map';
}

export interface ChatPart {
  text?: string;
  inlineData?: {
    mimeType: string;
    data: string; // base64 encoded
  };
  functionCall?: {
    name: string;
    args: any;
  };
  searchResults?: SearchResult[];
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  parts: ChatPart[];
}

export interface ChatSession {
  id:string;
  title: string;
  messages: ChatMessage[];
}

import React from 'react';
import { BotIcon, MoonIcon, PaletteIcon, SunIcon, TrashIcon, TypeIcon, CodeIcon } from './Icons';
import type { UIStyle, AccentColor, FontSize } from '../types';

interface SettingsModalProps {
    isOpen: boolean;
    onClose: () => void;
    uiStyle: UIStyle;
    setUiStyle: (style: UIStyle) => void;
    accentColor: AccentColor;
    setAccentColor: (color: AccentColor) => void;
    fontSize: FontSize;
    setFontSize: (size: FontSize) => void;
    isDarkMode: boolean;
    setIsDarkMode: (isDark: boolean) => void;
    onClearHistory: () => void;
    systemInstruction: string;
    setSystemInstruction: (val: string) => void;
}

const StyleCard: React.FC<{ 
    active: boolean; 
    onClick: () => void; 
    title: string; 
    previewClass: string;
    accentColor: string;
    fontClass?: string;
}> = ({ active, onClick, title, previewClass, accentColor, fontClass }) => (
    <button 
        onClick={onClick}
        className={`relative flex flex-col items-center gap-3 p-3 rounded-2xl border-2 transition-all duration-300 w-full group overflow-hidden
            ${active 
            ? `border-${accentColor}-600 bg-${accentColor}-50 dark:bg-${accentColor}-900/10` 
            : `border-transparent bg-gray-100 dark:bg-gray-800 hover:scale-[1.02]`
        }`}
    >
        <div className={`w-full h-16 rounded-xl shadow-sm ${previewClass} flex items-center justify-center text-xs font-bold transition-all ${fontClass}`}>
            Aa
        </div>
        <span className={`text-sm font-semibold ${active ? `text-${accentColor}-600` : 'text-gray-600 dark:text-gray-400'}`}>
            {title}
        </span>
        {active && (
            <div className={`absolute top-2 right-2 w-2.5 h-2.5 bg-${accentColor}-600 rounded-full animate-fade-in shadow-sm`} />
        )}
    </button>
);

const ColorOption: React.FC<{
    color: AccentColor;
    active: boolean;
    onClick: () => void;
    bgClass: string;
}> = ({ color, active, onClick, bgClass }) => (
    <button
        onClick={onClick}
        className={`w-9 h-9 rounded-full flex items-center justify-center transition-all duration-300 ${bgClass} shadow-sm ${active ? 'ring-2 ring-offset-2 ring-gray-400 dark:ring-gray-600 scale-110' : 'hover:scale-110 hover:shadow-md'}`}
        aria-label={`Select ${color} accent`}
    >
        {active && <div className="w-2 h-2 bg-white rounded-full shadow-sm" />}
    </button>
);

const FontSizeOption: React.FC<{
    size: FontSize;
    active: boolean;
    onClick: () => void;
    label: string;
    accentColor: string;
}> = ({ size, active, onClick, label, accentColor }) => (
    <button
        onClick={onClick}
        className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all
            ${active 
                ? `bg-white dark:bg-gray-700 text-${accentColor}-600 shadow-sm` 
                : 'text-gray-500 hover:bg-white/50 dark:hover:bg-gray-700/50'
            }`}
    >
        {label}
    </button>
);

export const SettingsModal: React.FC<SettingsModalProps> = ({ 
    isOpen, onClose, uiStyle, setUiStyle, accentColor, setAccentColor, fontSize, setFontSize, isDarkMode, setIsDarkMode, onClearHistory, systemInstruction, setSystemInstruction
}) => {
    if (!isOpen) return null;

    return (
        <div
            className="fixed inset-0 bg-black/40 backdrop-blur-md flex items-center justify-center z-[70] animate-fade-in p-4"
            onClick={onClose}
            role="dialog"
            aria-modal="true"
        >
            <div
                className={`w-full max-w-2xl bg-white dark:bg-gray-900 rounded-[2rem] shadow-2xl flex flex-col max-h-[90vh] overflow-hidden animate-fade-in-up border border-gray-100 dark:border-gray-800`}
                onClick={(e) => e.stopPropagation()}
            >
                <header className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-800 shrink-0">
                    <div className="flex items-center gap-3">
                        <div className={`p-2.5 rounded-2xl bg-${accentColor}-100 dark:bg-${accentColor}-900/30 text-${accentColor}-600`}>
                            <PaletteIcon className="w-5 h-5" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-gray-900 dark:text-white leading-tight">Preferences</h2>
                            <p className="text-xs text-gray-500">Customize your Cognix experience</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="w-8 h-8 flex items-center justify-center rounded-full bg-gray-100 dark:bg-gray-800 text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors font-bold text-lg">
                        &times;
                    </button>
                </header>

                <div className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar">

                    {/* UI Design Language */}
                    <section>
                        <h3 className="text-xs font-bold uppercase tracking-wider text-gray-400 mb-4 pl-1">Visual Identity</h3>
                        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                            <StyleCard 
                                title="Modern" 
                                active={uiStyle === 'modern'} 
                                onClick={() => setUiStyle('modern')}
                                previewClass="bg-white border border-gray-200"
                                accentColor={accentColor}
                            />
                            <StyleCard 
                                title="Retro" 
                                active={uiStyle === 'retro'} 
                                onClick={() => setUiStyle('retro')}
                                previewClass="bg-black border border-green-900 text-green-500 font-mono"
                                fontClass="font-mono"
                                accentColor="emerald"
                            />
                            <StyleCard 
                                title="Glass" 
                                active={uiStyle === 'glass'} 
                                onClick={() => setUiStyle('glass')}
                                previewClass="bg-gradient-to-br from-blue-100 to-purple-100 dark:from-blue-900 dark:to-purple-900"
                                accentColor={accentColor}
                            />
                            <StyleCard 
                                title="Brutal" 
                                active={uiStyle === 'brutal'} 
                                onClick={() => setUiStyle('brutal')}
                                previewClass="bg-white border-2 border-black"
                                accentColor={accentColor}
                            />
                        </div>
                    </section>

                    {/* Customization Row */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                        <section>
                            <h3 className="text-xs font-bold uppercase tracking-wider text-gray-400 mb-4 pl-1">Accent Color</h3>
                            <div className="flex flex-wrap gap-3">
                                {(['blue', 'violet', 'emerald', 'rose', 'amber'] as AccentColor[]).map(c => (
                                    <ColorOption key={c} color={c} active={accentColor === c} onClick={() => setAccentColor(c)} bgClass={`bg-${c}-600`} />
                                ))}
                            </div>
                        </section>

                        <section>
                            <div className="flex items-center gap-2 mb-4 pl-1">
                                <h3 className="text-xs font-bold uppercase tracking-wider text-gray-400">Typography</h3>
                            </div>
                            <div className="flex gap-1 p-1 bg-gray-100 dark:bg-gray-800 rounded-xl">
                                <FontSizeOption size="small" active={fontSize === 'small'} onClick={() => setFontSize('small')} label="Small" accentColor={accentColor} />
                                <FontSizeOption size="normal" active={fontSize === 'normal'} onClick={() => setFontSize('normal')} label="Medium" accentColor={accentColor} />
                                <FontSizeOption size="large" active={fontSize === 'large'} onClick={() => setFontSize('large')} label="Large" accentColor={accentColor} />
                            </div>
                        </section>
                    </div>

                    {/* Persona / System Prompt */}
                     <section>
                        <div className="flex items-center gap-2 mb-4 pl-1">
                            <CodeIcon className="w-4 h-4 text-gray-400" />
                            <h3 className="text-xs font-bold uppercase tracking-wider text-gray-400">System Persona</h3>
                        </div>
                        <div className="relative">
                            <textarea 
                                value={systemInstruction}
                                onChange={(e) => setSystemInstruction(e.target.value)}
                                className="w-full h-24 p-4 bg-gray-50 dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm leading-relaxed resize-none"
                                placeholder="e.g., You are a helpful coding assistant who speaks like a pirate..."
                            />
                        </div>
                    </section>

                    {/* Theme Mode */}
                    <section>
                        <h3 className="text-xs font-bold uppercase tracking-wider text-gray-400 mb-4 pl-1">Appearance</h3>
                        <div className="flex gap-3">
                            <button 
                                onClick={() => setIsDarkMode(false)}
                                className={`flex-1 flex items-center justify-center gap-3 py-3 rounded-xl text-sm font-bold transition-all border
                                    ${!isDarkMode ? 'bg-white border-gray-200 text-gray-900 shadow-sm' : 'bg-transparent border-transparent text-gray-400 hover:bg-gray-100'}`}
                            >
                                <SunIcon className="w-4 h-4" /> Light Mode
                            </button>
                            <button 
                                onClick={() => setIsDarkMode(true)}
                                className={`flex-1 flex items-center justify-center gap-3 py-3 rounded-xl text-sm font-bold transition-all border
                                    ${isDarkMode ? 'bg-gray-800 border-gray-700 text-white shadow-sm' : 'bg-transparent border-transparent text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'}`}
                            >
                                <MoonIcon className="w-4 h-4" /> Dark Mode
                            </button>
                        </div>
                    </section>

                    {/* Danger Zone */}
                    <section>
                         <div className="p-4 rounded-xl border border-red-100 dark:border-red-900/30 bg-red-50 dark:bg-red-900/10 flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-red-100 dark:bg-red-900/30 rounded-lg text-red-600">
                                    <TrashIcon className="w-5 h-5" />
                                </div>
                                <div>
                                    <h4 className="font-bold text-red-700 dark:text-red-400 text-sm">Clear History</h4>
                                    <p className="text-xs text-red-600/70 dark:text-red-400/70">Delete all local chats</p>
                                </div>
                            </div>
                            <button
                                onClick={onClearHistory}
                                className="px-4 py-2 text-xs font-bold text-white bg-red-600 hover:bg-red-700 rounded-lg transition-colors shadow-sm"
                            >
                                Delete
                            </button>
                        </div>
                    </section>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize } from '../types';
import { ai } from '../services/gemini';
import { BotIcon, SendIcon, SearchIcon, UserIcon, ImageIcon, XIcon, SpeakerIcon, CopyIcon, EditIcon, CheckIcon } from './Icons';
import { Modality } from "@google/genai";

const speakText = async (text: string) => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: text.slice(0, 400) }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
            },
        });
        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) new Audio(`data:audio/mp3;base64,${base64Audio}`).play();
    } catch (e) { console.error("TTS Error:", e); }
};

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, uiStyle, theme, fontSize, systemInstruction }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
  }, [messages, isLoading, selectedImage]);

  useEffect(() => {
    if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
        textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 150)}px`;
    }
  }, [input]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = reader.result as string;
            const base64Data = base64String.split(',')[1];
            setSelectedImage({ data: base64Data, mimeType: file.type });
        };
        reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSendMessage = useCallback(async (prompt?: string) => {
    const textInput = (prompt || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    let updatedMessages = [...messages];
    if (editingId) {
        const index = messages.findIndex(m => m.id === editingId);
        if (index !== -1) updatedMessages = messages.slice(0, index);
        setEditingId(null);
    }

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }] };

    updatedMessages.push(userMessage, modelPlaceholder);
    setMessages(updatedMessages);

    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const history = updatedMessages.slice(0, -2).map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      })).filter(m => m.parts.length > 0);

      let stream = await ai.models.generateContentStream({
          model: 'gemini-2.5-flash',
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { systemInstruction, tools: [{ googleSearch: {} }] },
      });

      let fullText = '';
      const collectedSearchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: fullText }] } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            collectedSearchResults.push(...results);
        }
      }

      if (collectedSearchResults.length > 0) {
        const unique = Array.from(new Map(collectedSearchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : "An unknown error occurred.";
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `Error: ${errorMessage}` }] } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, setMessages, messages, selectedImage, editingId, systemInstruction]);

  const handleEdit = (msg: ChatMessage) => {
      const textPart = msg.parts.find(p => p.text)?.text || '';
      setInput(textPart);
      setEditingId(msg.id);
      if (textareaRef.current) textareaRef.current.focus();
  };

  const handleCopy = (text: string, id: string) => {
      navigator.clipboard.writeText(text);
      setCopiedId(id);
      setTimeout(() => setCopiedId(null), 2000);
  };

  const getFontSizeClass = () => {
      switch(fontSize) {
          case 'small': return 'text-sm leading-relaxed';
          case 'large': return 'text-lg leading-relaxed';
          default: return 'text-[15px] leading-relaxed';
      }
  };

  // --- RETRO MODE RENDER ---
  if (uiStyle === 'retro') {
      return (
          <div className="flex flex-col h-full bg-black text-green-500 font-mono relative overflow-hidden">
              <div className="retro-scanlines"></div>
              <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-4 pb-32 no-scrollbar">
                  {messages.length === 0 ? (
                      <div className="flex flex-col items-center justify-center h-full opacity-50">
                          <pre className="text-xs sm:text-sm leading-tight text-center">
{`
   ______                  _      
  / ____/___  ____ _____  (_)  __ 
 / /   / __ \\/ __ \`/ __ \\/ / |/_/ 
/ /___/ /_/ / /_/ / / / / />  <   
\\____/\\____/\\__, /_/ /_/_/_/|_|   
           /____/                 
`}
                          </pre>
                          <p className="mt-4 animate-pulse">SYSTEM READY. AWAITING INPUT...</p>
                      </div>
                  ) : (
                      <div className="space-y-4">
                          {messages.map((msg) => (
                              <div key={msg.id} className="flex flex-col gap-1">
                                  <div className="text-xs opacity-50 uppercase border-b border-green-900 pb-1 mb-1 w-full flex justify-between">
                                      <span>[{msg.role === 'user' ? 'USER' : 'COGNIX'}]</span>
                                      <span>{new Date().toLocaleTimeString()}</span>
                                  </div>
                                  <div className="pl-2 border-l border-green-700 retro-glow">
                                      {msg.parts.map((part, i) => (
                                          <div key={i}>
                                              {part.inlineData && <div className="text-xs">[IMAGE DATA ATTACHED]</div>}
                                              <div className="whitespace-pre-wrap">{part.text}</div>
                                          </div>
                                      ))}
                                  </div>
                              </div>
                          ))}
                          {isLoading && <div className="animate-pulse text-green-300">{`> PROCESSING...`}</div>}
                      </div>
                  )}
              </div>
              <div className="p-4 border-t border-green-800 bg-black z-10">
                  <div className="flex items-center gap-2">
                      <span className="animate-pulse">{`>`}</span>
                      <textarea
                          ref={textareaRef}
                          value={input}
                          onChange={e => setInput(e.target.value)}
                          onKeyDown={e => { if(e.key==='Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); }}}
                          className="flex-1 bg-transparent border-none outline-none focus:ring-0 resize-none text-green-500 placeholder-green-900 h-6 font-mono"
                          rows={1}
                          autoComplete="off"
                          placeholder="ENTER COMMAND..."
                      />
                      <button onClick={() => handleSendMessage()} disabled={isLoading} className="text-xs border border-green-600 px-2 py-1 hover:bg-green-900">[SEND]</button>
                  </div>
              </div>
          </div>
      );
  }

  // --- MODERN / DEFAULT RENDER ---
  return (
    <div className="flex flex-col h-full relative">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-0 pb-36 no-scrollbar scroll-smooth">
        {messages.length === 0 && !isLoading ? (
            <div className="flex flex-col items-center justify-center min-h-[70vh] animate-fade-in p-6">
                <div className="text-center mb-10">
                    <div className={`w-20 h-20 mx-auto flex items-center justify-center mb-6 transition-all duration-500
                        ${uiStyle === 'brutal' 
                            ? `bg-white border-4 border-black shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] text-black` 
                            : `rounded-[2rem] shadow-2xl ${theme.gradient}`
                        }`}>
                        <BotIcon className={`w-10 h-10 ${uiStyle === 'brutal' ? 'text-black' : 'text-white'}`} />
                    </div>
                    <h1 className="text-4xl font-bold text-gray-900 dark:text-white mb-3 tracking-tight">
                        Cognix AI
                    </h1>
                    <p className="text-gray-500 dark:text-gray-400 text-lg font-medium">How can I help you today?</p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 w-full max-w-2xl">
                     {/* Suggestion cards would go here - simplified for brevity */}
                </div>
            </div>
        ) : (
            <div className="flex flex-col space-y-6 max-w-3xl mx-auto w-full pt-8 px-4 sm:px-0">
                {messages.map((msg, idx) => (
                  <div key={msg.id} className={`flex gap-4 group ${msg.role === 'user' ? 'justify-end' : 'justify-start'} ${idx === messages.length-1 ? 'animate-fade-in-up' : ''}`}>
                    {msg.role === 'model' && (
                        <div className={`w-8 h-8 flex items-center justify-center shrink-0 mt-1 transition-all duration-300
                            ${uiStyle === 'brutal' ? `bg-white border-2 border-black rounded-none shadow-[2px_2px_0px_0px_rgba(0,0,0,1)]` 
                            : `rounded-xl shadow-sm ${theme.gradient}`}`}>
                            <BotIcon className={`w-5 h-5 ${uiStyle === 'brutal' ? 'text-black' : 'text-white'}`} />
                        </div>
                    )}

                    <div className={`flex flex-col gap-2 max-w-[85%] sm:max-w-[75%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                        {msg.parts.map((part, pIdx) => (
                            <div key={pIdx} className={`relative px-5 py-3.5 ${getFontSizeClass()} transition-all duration-300
                                ${msg.role === 'user' 
                                    ? uiStyle === 'brutal' 
                                        ? `bg-white text-black border-2 border-black shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]` 
                                        : uiStyle === 'glass'
                                            ? `${theme.primary}/80 backdrop-blur-md text-white rounded-2xl rounded-tr-sm shadow-lg border border-white/10`
                                            : `${theme.primary} text-white rounded-2xl rounded-tr-sm shadow-md`
                                    : uiStyle === 'brutal'
                                        ? 'bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 border-2 border-black dark:border-gray-200 shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] dark:shadow-[4px_4px_0px_0px_rgba(255,255,255,1)]'
                                        : uiStyle === 'glass'
                                            ? 'bg-white/60 dark:bg-gray-800/60 backdrop-blur-md text-gray-900 dark:text-gray-100 border border-white/20 rounded-2xl rounded-tl-sm shadow-sm'
                                            : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-100 border border-gray-100 dark:border-gray-700 rounded-2xl rounded-tl-sm shadow-sm'
                                }`}>
                                {part.inlineData && (
                                    <div className="rounded-lg overflow-hidden mb-3 border border-white/20">
                                        <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="max-w-full max-h-64 object-cover" alt="User upload" />
                                    </div>
                                )}
                                {part.text && <div className="markdown-body whitespace-pre-wrap">{part.text}</div>}
                                {part.searchResults && part.searchResults.length > 0 && (
                                    <div className="mt-3 pt-3 border-t border-black/10 dark:border-white/10 flex flex-wrap gap-2">
                                        {part.searchResults.map((r, i) => (
                                            <a key={i} href={r.uri} target="_blank" className="flex items-center gap-1.5 text-xs bg-black/5 dark:bg-white/5 px-2.5 py-1.5 rounded-md hover:bg-black/10 dark:hover:bg-white/10 transition-colors font-medium">
                                                <SearchIcon className="w-3.5 h-3.5"/> {r.title}
                                            </a>
                                        ))}
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                  </div>
                ))}
            </div>
        )}
      </div>

      <div className="absolute bottom-4 left-0 right-0 px-4 z-20">
        <div className="max-w-3xl mx-auto">
            {/* Input Area */}
            <div className={`relative flex items-end gap-2 p-2 pl-4 transition-all duration-300
                ${uiStyle === 'brutal' 
                    ? 'bg-white dark:bg-gray-800 border-2 border-black dark:border-gray-200 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] rounded-none'
                    : uiStyle === 'glass'
                        ? 'bg-white/60 dark:bg-gray-900/60 backdrop-blur-xl border border-white/20 rounded-[2rem] shadow-2xl'
                        : 'bg-white dark:bg-gray-800 rounded-[2rem] shadow-[0_8px_30px_rgb(0,0,0,0.12)] border border-gray-100 dark:border-gray-700'
                }`}>
                <input type="file" ref={fileInputRef} onChange={handleImageSelect} accept="image/*" className="hidden" />
                <button
                    onClick={() => fileInputRef.current?.click()}
                    className={`p-2.5 mb-1.5 rounded-full text-gray-400 hover:${theme.text} ${theme.bgSoft} transition-colors`}
                >
                    <ImageIcon className="w-6 h-6" />
                </button>
                <textarea
                    ref={textareaRef}
                    value={input}
                    onChange={e => setInput(e.target.value)}
                    onKeyDown={e => { if(e.key==='Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); }}}
                    placeholder="Message Cognix..."
                    className={`flex-1 bg-transparent border-none outline-none focus:ring-0 resize-none py-3.5 max-h-32 text-gray-800 dark:text-gray-100 placeholder-gray-400 ${getFontSizeClass()}`}
                    rows={1}
                />
                <button 
                    onClick={() => handleSendMessage()} 
                    disabled={(!input.trim() && !selectedImage) || isLoading}
                    className={`p-3 m-1 ${theme.primary} text-white ${theme.primaryHover} disabled:opacity-50 transition-all flex-shrink-0
                             ${uiStyle === 'brutal' 
                                ? 'rounded-none border border-black shadow-[2px_2px_0px_0px_rgba(0,0,0,1)]' 
                                : 'rounded-full shadow-lg hover:scale-105 active:scale-95'}`}
                >
                    <SendIcon className="w-5 h-5" />
                </button>
            </div>
            <div className="text-center mt-3">
                 <p className="text-[10px] font-medium uppercase tracking-widest text-gray-300 dark:text-gray-600">Cognix AI</p>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, UIStyle, ThemeColors } from '../types';
import { NewChatIcon, TrashIcon, PencilIcon, MicrophoneIcon, BotIcon, SettingsIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  onRenameChat: (id: string, newTitle: string) => void;
  onOpenSettings: () => void;
  uiStyle: UIStyle;
  theme: ThemeColors;
}

export const Sidebar: React.FC<SidebarProps> = ({
  chatHistory,
  activeChatId,
  mode,
  onSetMode,
  onSelectChat,
  onNewChat,
  onDeleteChat,
  onRenameChat,
  onOpenSettings,
  uiStyle,
  theme,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleStartEditing = (chat: ChatSession) => {
    setEditingChatId(chat.id);
    setNewTitle(chat.title);
  };

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) onRenameChat(editingChatId, newTitle.trim());
    setEditingChatId(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleRename();
    else if (e.key === 'Escape') setEditingChatId(null);
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    onDeleteChat(id);
  };

  // --- RETRO SIDEBAR ---
  if (uiStyle === 'retro') {
      return (
          <aside className="flex flex-col h-full bg-black text-green-600 font-mono border-r border-green-900 z-10">
              <div className="p-4 border-b border-green-900">
                  <div className="text-xl font-bold retro-glow mb-4">COGNIX_TERM_V2</div>
                  <button onClick={onNewChat} className="w-full text-left border border-green-600 p-2 hover:bg-green-900 hover:text-green-300 transition-colors">
                      [+ NEW SESSION]
                  </button>
              </div>
              <div className="flex-1 overflow-y-auto p-2 no-scrollbar">
                  <div className="text-xs opacity-50 mb-2">--- ACTIVE SESSIONS ---</div>
                  {chatHistory.map(chat => (
                      <div key={chat.id} onClick={() => onSelectChat(chat.id)} className={`cursor-pointer p-1 hover:text-green-300 truncate ${activeChatId === chat.id ? 'bg-green-900 text-white' : ''}`}>
                          {activeChatId === chat.id ? '>' : ' '} {chat.title}
                      </div>
                  ))}
              </div>
              <div className="p-2 border-t border-green-900">
                 <button onClick={onOpenSettings} className="w-full text-left p-2 hover:bg-green-900">[SETTINGS]</button>
                 <button onClick={() => onSetMode('live')} className="w-full text-left p-2 hover:bg-green-900">[LIVE LINK]</button>
              </div>
          </aside>
      );
  }

  // --- MODERN / DEFAULT SIDEBAR ---
  return (
    <aside className="flex flex-col h-full text-gray-800 dark:text-gray-200 relative z-10">
      <div className="p-6 pb-2">
        <div className="flex items-center gap-3 mb-8 px-1">
            <div className={`w-8 h-8 flex items-center justify-center transition-all duration-300
                 ${uiStyle === 'brutal' ? 'bg-white border-2 border-black shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] rounded-none' 
                 : `rounded-xl ${theme.gradient} shadow-lg shadow-blue-500/20`}`}>
                <BotIcon className={`w-5 h-5 ${uiStyle === 'brutal' ? 'text-black' : 'text-white'}`} />
            </div>
            <span className="text-xl font-bold tracking-tight text-gray-900 dark:text-white">Cognix</span>
        </div>

        <button
          onClick={onNewChat}
          className={`w-full group flex items-center justify-between gap-2 px-5 py-4 font-semibold transition-all duration-200
            ${uiStyle === 'brutal' 
                ? 'bg-black text-white dark:bg-white dark:text-black rounded-none border border-transparent shadow-[4px_4px_0px_0px_rgba(100,100,100,1)] hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-[2px_2px_0px_0px_rgba(100,100,100,1)]'
                : 'rounded-2xl bg-gray-900 dark:bg-white text-white dark:text-gray-900 shadow-xl hover:shadow-2xl hover:-translate-y-0.5'}`}
        >
          <span>New Chat</span>
          <NewChatIcon className="w-5 h-5 opacity-70 group-hover:opacity-100 group-hover:rotate-90 transition-all" />
        </button>
      </div>

      <div className="px-4 py-2 space-y-2">
        <button
            onClick={() => onSetMode('live')}
            className={`w-full flex items-center gap-3 px-4 py-3.5 text-sm font-bold transition-all duration-200
                ${uiStyle === 'brutal' ? 'rounded-none border border-transparent hover:border-black hover:bg-blue-50' : 'rounded-2xl'}
                ${mode === 'live'
                ? uiStyle === 'brutal' ? 'bg-blue-100 border-black font-bold' : `${theme.bgSoft} ${theme.text}`
                : 'text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800/60'
            }`}
        >
            <MicrophoneIcon className={`w-5 h-5 ${mode === 'live' ? theme.text : 'text-gray-400'}`} />
            Live Conversation
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-4 pb-6 mt-4 no-scrollbar">
        <h3 className="px-4 mb-3 text-[10px] font-bold text-gray-400 dark:text-gray-600 uppercase tracking-widest">History</h3>
        <div className="space-y-1">
            {chatHistory.map((chat) => (
            <div
                key={chat.id}
                onClick={() => editingChatId !== chat.id && onSelectChat(chat.id)}
                className={`group relative flex items-center justify-between px-4 py-3 cursor-pointer transition-all duration-200
                ${uiStyle === 'brutal' ? 'rounded-none border-b border-gray-200 dark:border-gray-800 hover:bg-gray-50' : 'rounded-2xl'}
                ${activeChatId === chat.id && mode === 'chat'
                    ? uiStyle === 'brutal' ? `bg-gray-100 dark:bg-gray-800 font-bold border-l-4 ${theme.border}` : `bg-white dark:bg-gray-800 shadow-md text-gray-900 dark:text-white font-semibold`
                    : 'text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800/50 hover:text-gray-900 dark:hover:text-gray-200'
                }`}
            >
                {editingChatId === chat.id ? (
                    <input
                        ref={inputRef}
                        type="text"
                        value={newTitle}
                        onChange={(e) => setNewTitle(e.target.value)}
                        onKeyDown={handleKeyDown}
                        onBlur={handleRename}
                        className={`w-full bg-transparent focus:outline-none text-sm border-b ${theme.border} py-0.5`}
                    />
                ) : (
                    <>
                        <span className="truncate text-sm pr-8">{chat.title}</span>
                        <div className={`absolute right-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-200
                             ${uiStyle !== 'brutal' ? 'bg-white dark:bg-gray-800 shadow-sm rounded-lg p-0.5 border border-gray-100 dark:border-gray-700' : ''}`}>
                            <button onClick={(e) => { e.stopPropagation(); handleStartEditing(chat); }} className={`p-1.5 rounded-md text-gray-400 hover:${theme.text} hover:${theme.bgSoft}`}>
                                <PencilIcon className="w-3.5 h-3.5" />
                            </button>
                            <button onClick={(e) => handleDelete(e, chat.id)} className="p-1.5 rounded-md text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20">
                                <TrashIcon className="w-3.5 h-3.5" />
                            </button>
                        </div>
                    </>
                )}
            </div>
            ))}
        </div>
      </div>

      <div className="p-4 border-t border-gray-100 dark:border-gray-800">
        <button 
            onClick={onOpenSettings}
            className={`w-full flex items-center gap-3 px-5 py-4 text-sm font-bold transition-all duration-200 text-gray-500 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-800
                 ${uiStyle === 'brutal' ? 'rounded-none hover:border-2 hover:border-black' : 'rounded-2xl'}`}
        >
            <SettingsIcon className="w-5 h-5" />
            Preferences
        </button>
      </div>
    </aside>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { MenuIcon, UsersIcon, CopyIcon, CheckIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import { ai } from './services/gemini';
import type { ChatMessage, ChatSession, Mode, UIStyle, AccentColor, ThemeColors, FontSize } from './types';

// Theme Definitions
const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', text: 'text-blue-600', textDark: 'text-blue-400', bgSoft: 'bg-blue-50', darkBgSoft: 'dark:bg-blue-900/20', border: 'border-blue-600', ring: 'focus:ring-blue-600', gradient: 'bg-gradient-to-tr from-blue-600 to-cyan-500' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-tr from-violet-600 to-fuchsia-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-tr from-emerald-600 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-tr from-rose-600 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-tr from-amber-600 to-orange-500' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [fontSize, setFontSize] = useState<FontSize>('normal');
  const [systemInstruction, setSystemInstruction] = useState("You are Cognix AI, a highly advanced assistant developed by Shashwat Ranjan Jha. Be concise and helpful.");
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Invite/Collab State
  const [isInviteOpen, setIsInviteOpen] = useState(false);
  const [inviteLink, setInviteLink] = useState('');
  const [isCopied, setIsCopied] = useState(false);
  const [friendCount, setFriendCount] = useState(0);
  const [toasts, setToasts] = useState<{id: string, message: string}[]>([]);

  // Chat State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);

  // Load state
  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_chat_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }

    const savedStyle = localStorage.getItem('cognix_style') as UIStyle;
    if (savedStyle) setUiStyle(savedStyle);

    const savedAccent = localStorage.getItem('cognix_accent') as AccentColor;
    if (savedAccent) setAccentColor(savedAccent);

    const savedFont = localStorage.getItem('cognix_font') as FontSize;
    if (savedFont) setFontSize(savedFont);

    const savedSys = localStorage.getItem('cognix_system_instruction');
    if (savedSys) setSystemInstruction(savedSys);
  }, []);

  useEffect(() => localStorage.setItem('cognix_chat_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('cognix_style', uiStyle), [uiStyle]);
  useEffect(() => localStorage.setItem('cognix_accent', accentColor), [accentColor]);
  useEffect(() => localStorage.setItem('cognix_font', fontSize), [fontSize]);
  useEffect(() => localStorage.setItem('cognix_system_instruction', systemInstruction), [systemInstruction]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  useEffect(() => {
    if (messages.length > 0 && !activeChatId) {
       if (messages[0].parts[0]?.text) {
          const newId = Date.now().toString();
          const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
          const newSession: ChatSession = {
            id: newId,
            title: firstUserText.slice(0, 30) + (firstUserText.length > 30 ? '...' : ''),
            messages: messages
          };
          setChatHistory(prev => [newSession, ...prev]);
          setActiveChatId(newId);
       }
    } else if (activeChatId && messages.length > 0) {
       setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
    }
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleOpenInvite = () => {
    const link = `${window.location.origin}?chat=${activeChatId || 'new'}-${Math.random().toString(36).substring(7)}`;
    setInviteLink(link);
    setIsInviteOpen(true);
    setIsCopied(false);
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(inviteLink);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
    if (friendCount < 10) {
        setTimeout(() => {
            const names = ["Alex", "Jordan", "Taylor", "Casey", "Riley"];
            const randomName = names[Math.floor(Math.random() * names.length)];
            const id = Date.now().toString();
            setToasts(prev => [...prev, { id, message: `${randomName} joined` }]);
            setFriendCount(prev => Math.min(prev + 1, 10));
            setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
        }, 3000);
    }
  };

  // Styles wrapper class
  const mainWrapperClass = useMemo(() => {
      switch(uiStyle) {
          case 'glass': return "bg-[url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2564&auto=format&fit=crop')] bg-cover bg-center";
          case 'brutal': return "bg-white dark:bg-gray-900";
          case 'retro': return "bg-black";
          default: return "bg-gray-50 dark:bg-gray-950"; // Liquid/Modern base
      }
  }, [uiStyle]);

  return (
    <div className={`flex h-[100dvh] overflow-hidden text-gray-900 dark:text-gray-100 font-sans selection:bg-${accentColor}-100 dark:selection:bg-${accentColor}-900/30 transition-all duration-300 ${mainWrapperClass}`}>
      {/* Toast Notifications */}
      <div className="fixed top-20 right-4 z-[70] flex flex-col gap-2 pointer-events-none">
        {toasts.map(toast => (
            <div key={toast.id} className="bg-gray-900 dark:bg-white text-white dark:text-gray-900 px-4 py-3 rounded-xl shadow-xl flex items-center gap-3 animate-fade-in-up">
                <div className="bg-green-500 rounded-full p-1"><CheckIcon className="w-3 h-3 text-white"/></div>
                <span className="text-sm font-medium">{toast.message}</span>
            </div>
        ))}
      </div>

      {/* Invite Modal */}
      {isInviteOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fade-in" onClick={() => setIsInviteOpen(false)}>
            <div className={`bg-white dark:bg-gray-900 rounded-3xl shadow-2xl max-w-md w-full overflow-hidden ${uiStyle === 'brutal' ? 'rounded-none border-2 border-black' : ''}`} onClick={e => e.stopPropagation()}>
                <div className="p-6">
                    <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-3">
                             <div className={`p-2 rounded-xl ${activeTheme.bgSoft} ${activeTheme.text}`}>
                                <UsersIcon className="w-6 h-6" />
                             </div>
                             <div>
                                 <h3 className="text-lg font-bold">Invite Friends</h3>
                                 <p className="text-sm text-gray-500">Collaborate with up to 10 friends.</p>
                             </div>
                        </div>
                        <button onClick={() => setIsInviteOpen(false)} className="text-gray-400 hover:text-gray-600">&times;</button>
                    </div>

                    <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-xl border border-gray-100 dark:border-gray-700 mb-6">
                        <div className="flex gap-2">
                            <input type="text" readOnly value={inviteLink} className="flex-1 bg-white dark:bg-gray-950 border border-gray-200 dark:border-gray-700 rounded-lg px-3 py-2 text-sm text-gray-600 dark:text-gray-300 focus:outline-none" />
                            <button onClick={handleCopyLink} className={`${activeTheme.primary} ${activeTheme.primaryHover} text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2`}>
                                {isCopied ? <CheckIcon className="w-4 h-4"/> : <CopyIcon className="w-4 h-4"/>}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      )}

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-40 md:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />}

      {/* Sidebar */}
      <div className={`
        fixed md:static inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out overflow-hidden h-full flex flex-col
        ${isSidebarOpen ? 'translate-x-0 w-80' : '-translate-x-full md:translate-x-0 w-80'}
        ${isDesktopSidebarOpen ? 'md:w-80' : 'md:w-0'}
        ${uiStyle === 'glass' ? 'bg-white/70 dark:bg-gray-900/70 backdrop-blur-xl border-r border-white/20' : ''}
        ${uiStyle === 'brutal' ? 'bg-white dark:bg-gray-900 border-r-2 border-black' : ''}
        ${uiStyle === 'retro' ? 'bg-black border-r border-green-900' : ''}
        ${uiStyle === 'modern' ? 'bg-gray-50/80 dark:bg-gray-900/90 backdrop-blur-2xl border-r border-gray-200/50 dark:border-gray-800/50' : ''}
      `}>
         <Sidebar 
            chatHistory={chatHistory}
            activeChatId={activeChatId}
            mode={mode}
            onSetMode={(m) => { setMode(m); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
            onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
            onNewChat={handleNewChat}
            onDeleteChat={(id) => {
                setChatHistory(h => h.filter(c => c.id !== id));
                if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
            }}
            onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
            onOpenSettings={() => setIsSettingsOpen(true)}
            uiStyle={uiStyle}
            theme={activeTheme}
         />
      </div>

      {/* Main Content */}
      <div className={`flex-1 flex flex-col h-full relative w-full min-w-0 transition-colors duration-300 
          ${uiStyle === 'glass' ? 'bg-white/30 dark:bg-black/40 backdrop-blur-lg' : ''}`}>
        {/* Header */}
        <header className={`h-16 flex items-center justify-between px-4 sm:px-6 z-30 shrink-0 sticky top-0
            ${uiStyle === 'retro' ? 'bg-black border-b border-green-900 text-green-500 font-mono' : ''}
            ${uiStyle === 'modern' ? 'backdrop-blur-md bg-white/50 dark:bg-black/20' : ''}
        `}>
          <div className="flex items-center gap-3 overflow-hidden">
            <button 
              onClick={() => window.innerWidth >= 768 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 -ml-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 text-gray-600 dark:text-gray-400 transition-colors"
            >
              <MenuIcon className="w-5 h-5" />
            </button>
            <h1 className="font-bold text-lg text-gray-800 dark:text-gray-100 truncate tracking-tight">
              {mode === 'live' ? 'Live Conversation' : (currentChat?.title || 'New Chat')}
            </h1>
          </div>

          <div className="flex items-center gap-2">
            {mode === 'chat' && (
                <button
                    onClick={handleOpenInvite}
                    className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-colors mr-2
                        ${uiStyle === 'brutal' ? 'bg-white border border-black text-black hover:bg-gray-50' 
                        : `${activeTheme.bgSoft} ${activeTheme.text} hover:opacity-80`}`}
                >
                    <UsersIcon className="w-4 h-4"/>
                    <span>Collaborate</span>
                    {friendCount > 0 && <span className={`${activeTheme.primary} text-white text-[10px] px-1.5 rounded-full`}>{friendCount}</span>}
                </button>
            )}
          </div>
        </header>

        {/* View Container */}
        <main className="flex-1 relative overflow-hidden flex flex-col">
          {mode === 'chat' && (
            <ChatView 
              messages={messages} 
              setMessages={val => {
                  if(typeof val === 'function') setMessages(prev => val(prev));
                  else setMessages(val);
              }}
              uiStyle={uiStyle}
              theme={activeTheme}
              fontSize={fontSize}
              systemInstruction={systemInstruction}
            />
          )}
          {mode === 'live' && <LiveView theme={activeTheme} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle}
        setUiStyle={setUiStyle}
        accentColor={accentColor}
        setAccentColor={setAccentColor}
        fontSize={fontSize}
        setFontSize={setFontSize}
        isDarkMode={isDarkMode}
        setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
        systemInstruction={systemInstruction}
        setSystemInstruction={setSystemInstruction}
      />
    </div>
  );
}

export default App;

