  // --- 2. BRUTAL (NEO-BRUTALISM) THEME ---
  if (uiStyle === 'brutal') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-zinc-900 relative">
             <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-6 pb-32 no-scrollbar space-y-8">
                {messages.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center">
                        <div className="bg-white border-4 border-black p-8 shadow-[8px_8px_0px_0px_rgba(0,0,0,1)]">
                            <h1 className="text-5xl font-black uppercase italic">Cognix</h1>
                            <p className="font-bold mt-2 bg-yellow-300 inline-block px-1">AI ASSISTANT</p>
                        </div>
                    </div>
                ) : (
                    messages.map((msg, idx) => (
                        <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} ${idx===messages.length-1 ? 'animate-fade-in-up' : ''}`}>
                             <div className={`max-w-[80%] border-4 border-black p-4 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] ${msg.role === 'user' ? 'bg-blue-500 text-white' : 'bg-white text-black'}`}>
                                 <div className="font-black text-xs uppercase mb-2 border-b-2 border-black/20 pb-1 flex justify-between gap-4">
                                     <span>{msg.role}</span>
                                     <span>#{msg.id.slice(-4)}</span>
                                 </div>
                                 {msg.parts.map((part, i) => (
                                     <div key={i} className={`whitespace-pre-wrap font-bold ${getFontSizeClass()}`}>
                                         {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="w-full border-2 border-black mb-2 grayscale hover:grayscale-0 transition-all" alt="upload"/>}
                                         {part.text}
