                       </div>
                   ) : (
                       <div className="space-y-6 pt-6">
                           {messages.map((msg, idx) => (
                               <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} ${idx===messages.length-1 ? 'animate-fade-in-up' : ''}`}>
                                   <div className={`max-w-[75%] p-6 rounded-3xl backdrop-blur-xl border border-white/20 shadow-lg ${msg.role === 'user' ? 'bg-white/20 text-white rounded-br-none' : 'bg-black/20 text-white rounded-bl-none'}`}>
                                       {msg.parts.map((part, i) => (
                                           <div key={i} className={`whitespace-pre-wrap ${getFontSizeClass()}`}>
                                               {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-xl mb-3 opacity-90" alt="upload"/>}
                                               {part.text}
                                           </div>
                                       ))}
                                   </div>
                               </div>
                           ))}
