import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, UIStyle, ThemeColors } from '../types';
import { NewChatIcon, TrashIcon, PencilIcon, MicrophoneIcon, BotIcon, SettingsIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  onRenameChat: (id: string, newTitle: string) => void;
  onOpenSettings: () => void;
  uiStyle: UIStyle;
  theme: ThemeColors;
}

export const Sidebar: React.FC<SidebarProps> = ({
  chatHistory,
  activeChatId,
  mode,
  onSetMode,
  onSelectChat,
  onNewChat,
  onDeleteChat,
  onRenameChat,
  onOpenSettings,
  uiStyle,
  theme,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleStartEditing = (chat: ChatSession) => {
    setEditingChatId(chat.id);
    setNewTitle(chat.title);
  };

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) onRenameChat(editingChatId, newTitle.trim());
    setEditingChatId(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleRename();
    else if (e.key === 'Escape') setEditingChatId(null);
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    onDeleteChat(id);
  };

  // --- RETRO SIDEBAR ---
  if (uiStyle === 'retro') {
      return (
          <aside className="flex flex-col h-full bg-black text-green-600 font-mono z-10">
              <div className="p-4 border-b border-green-900">
                  <div className="text-xl font-bold retro-glow mb-4">COGNIX_TERM_V2</div>
                  <button onClick={onNewChat} className="w-full text-left border border-green-600 p-2 hover:bg-green-900 hover:text-green-300 transition-colors">
                      [+ NEW SESSION]
                  </button>
              </div>
              <div className="flex-1 overflow-y-auto p-2 no-scrollbar">
                  <div className="text-xs opacity-50 mb-2">--- ACTIVE SESSIONS ---</div>
                  {chatHistory.map(chat => (
                      <div key={chat.id} onClick={() => onSelectChat(chat.id)} className={`cursor-pointer p-1 hover:text-green-300 truncate ${activeChatId === chat.id ? 'bg-green-900 text-white' : ''}`}>
                          {activeChatId === chat.id ? '>' : ' '} {chat.title}
                      </div>
                  ))}
              </div>
              <div className="p-2 border-t border-green-900">
                 <button onClick={onOpenSettings} className="w-full text-left p-2 hover:bg-green-900">[SETTINGS]</button>
                 <button onClick={() => onSetMode('live')} className="w-full text-left p-2 hover:bg-green-900">[LIVE LINK]</button>
              </div>
          </aside>
      );
  }

  // --- BRUTAL SIDEBAR ---
  if (uiStyle === 'brutal') {
       return (
        <aside className="flex flex-col h-full bg-white dark:bg-zinc-900 text-black dark:text-white z-10">
            <div className="p-6 border-b-4 border-black">
                <h1 className="text-3xl font-black uppercase mb-4 italic">Menu</h1>
                <button onClick={onNewChat} className="w-full bg-black text-white p-3 font-bold uppercase shadow-[4px_4px_0px_0px_rgba(100,100,100,1)] hover:translate-x-1 hover:translate-y-1 hover:shadow-none transition-all">
                    Start New Chat
                </button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-2">
                {chatHistory.map(chat => (
                     <div key={chat.id} onClick={() => onSelectChat(chat.id)} className={`p-3 border-2 border-black font-bold cursor-pointer ${activeChatId === chat.id ? 'bg-yellow-300 text-black shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]' : 'hover:bg-gray-100'}`}>
                         {chat.title}
                     </div>
                ))}
            </div>
             <div className="p-4 border-t-4 border-black">
                 <button onClick={onOpenSettings} className="w-full border-2 border-black p-3 font-bold uppercase hover:bg-gray-100">Preferences</button>
             </div>
        </aside>
       )
  }

  // --- GLASS / MODERN SIDEBAR ---
  return (
    <aside className="flex flex-col h-full text-gray-800 dark:text-gray-200 relative z-10">
      <div className="p-6 pb-2">
        <div className="flex items-center gap-3 mb-8 px-1">
            <div className={`w-8 h-8 flex items-center justify-center rounded-xl ${theme.gradient} shadow-lg shadow-blue-500/20`}>
                <BotIcon className="w-5 h-5 text-white" />
            </div>
            <span className="text-xl font-bold tracking-tight text-gray-900 dark:text-white">Cognix</span>
        </div>

        <button
          onClick={onNewChat}
          className={`w-full group flex items-center justify-between gap-2 px-5 py-3.5 font-semibold transition-all duration-200 rounded-xl bg-gray-900 dark:bg-white text-white dark:text-gray-900 shadow-lg hover:shadow-xl hover:-translate-y-0.5`}
        >
          <span>New Chat</span>
          <NewChatIcon className="w-5 h-5 opacity-70 group-hover:opacity-100 group-hover:rotate-90 transition-all" />
        </button>
      </div>

      <div className="px-4 py-2 space-y-2">
        <button
            onClick={() => onSetMode('live')}
            className={`w-full flex items-center gap-3 px-4 py-3 text-sm font-bold transition-all duration-200 rounded-xl
                ${mode === 'live' ? `${theme.bgSoft} ${theme.text}` : 'text-gray-500 hover:bg-gray-50 dark:hover:bg-gray-800/60'}`}
        >
            <MicrophoneIcon className={`w-5 h-5 ${mode === 'live' ? theme.text : 'text-gray-400'}`} />
            Live Conversation
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-4 pb-6 mt-4 no-scrollbar">
        <h3 className="px-4 mb-3 text-[10px] font-bold text-gray-400 dark:text-gray-600 uppercase tracking-widest">History</h3>
        <div className="space-y-1">
            {chatHistory.map((chat) => (
            <div
                key={chat.id}
                onClick={() => editingChatId !== chat.id && onSelectChat(chat.id)}
                className={`group relative flex items-center justify-between px-4 py-3 cursor-pointer transition-all duration-200 rounded-xl
                ${activeChatId === chat.id && mode === 'chat'
                    ? `bg-white dark:bg-zinc-800 shadow-sm text-gray-900 dark:text-white font-semibold border border-gray-100 dark:border-zinc-700`
                    : 'text-gray-500 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-zinc-800/50 hover:text-gray-900 dark:hover:text-gray-200'
                }`}
            >
                {editingChatId === chat.id ? (
                    <input
                        ref={inputRef}
                        type="text"
                        value={newTitle}
                        onChange={(e) => setNewTitle(e.target.value)}
                        onKeyDown={handleKeyDown}
                        onBlur={handleRename}
                        className={`w-full bg-transparent focus:outline-none text-sm border-b ${theme.border} py-0.5`}
                    />
                ) : (
                    <>
                        <span className="truncate text-sm pr-8">{chat.title}</span>
                        <div className="absolute right-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-200 bg-white dark:bg-zinc-800 shadow-sm rounded-lg p-0.5 border border-gray-100 dark:border-zinc-700">
                            <button onClick={(e) => { e.stopPropagation(); handleStartEditing(chat); }} className={`p-1.5 rounded-md text-gray-400 hover:${theme.text} hover:${theme.bgSoft}`}>
                                <PencilIcon className="w-3.5 h-3.5" />
                            </button>
                            <button onClick={(e) => handleDelete(e, chat.id)} className="p-1.5 rounded-md text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20">
                                <TrashIcon className="w-3.5 h-3.5" />
                            </button>
                        </div>
                    </>
                )}
            </div>
            ))}
        </div>
      </div>

      <div className="p-4 border-t border-gray-100 dark:border-zinc-800">
        <button 
            onClick={onOpenSettings}
            className="w-full flex items-center gap-3 px-5 py-4 text-sm font-bold transition-all duration-200 text-gray-500 hover:text-gray-900 dark:hover:text-white hover:bg-gray-50 dark:hover:bg-zinc-800 rounded-xl"
        >
            <SettingsIcon className="w-5 h-5" />
            Preferences
        </button>
      </div>
    </aside>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { MenuIcon, UsersIcon, CopyIcon, CheckIcon, XIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import { ai } from './services/gemini';
import type { ChatMessage, ChatSession, Mode, UIStyle, AccentColor, ThemeColors, FontSize } from './types';

// Theme Configuration
const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-blue-500', primaryHover: 'hover:bg-blue-600', text: 'text-blue-600', textDark: 'text-blue-400', bgSoft: 'bg-blue-50', darkBgSoft: 'dark:bg-blue-900/20', border: 'border-blue-500', ring: 'focus:ring-blue-500', gradient: 'bg-gradient-to-tr from-blue-400 to-blue-600' },
    violet: { primary: 'bg-violet-500', primaryHover: 'hover:bg-violet-600', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-500', ring: 'focus:ring-violet-500', gradient: 'bg-gradient-to-tr from-violet-400 to-fuchsia-600' },
    emerald: { primary: 'bg-emerald-500', primaryHover: 'hover:bg-emerald-600', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-500', ring: 'focus:ring-emerald-500', gradient: 'bg-gradient-to-tr from-emerald-400 to-teal-600' },
    rose: { primary: 'bg-rose-500', primaryHover: 'hover:bg-rose-600', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-500', ring: 'focus:ring-rose-500', gradient: 'bg-gradient-to-tr from-rose-400 to-red-600' },
    amber: { primary: 'bg-amber-500', primaryHover: 'hover:bg-amber-600', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-500', ring: 'focus:ring-amber-500', gradient: 'bg-gradient-to-tr from-amber-400 to-orange-600' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [fontSize, setFontSize] = useState<FontSize>('normal');
  const [systemInstruction, setSystemInstruction] = useState("You are Cognix AI. Be helpful and concise.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false); // Mobile
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true); // Desktop

  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Data State
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);

  // Invite State
  const [isInviteOpen, setIsInviteOpen] = useState(false);
  const [inviteLink, setInviteLink] = useState('');
  const [isCopied, setIsCopied] = useState(false);

  // Persistence
  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_chat_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }

    const savedStyle = localStorage.getItem('cognix_style') as UIStyle;
    if (savedStyle) setUiStyle(savedStyle);

    const savedAccent = localStorage.getItem('cognix_accent') as AccentColor;
    if (savedAccent) setAccentColor(savedAccent);

    const savedSys = localStorage.getItem('cognix_system_instruction');
    if (savedSys) setSystemInstruction(savedSys);
  }, []);

  useEffect(() => localStorage.setItem('cognix_chat_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('cognix_style', uiStyle), [uiStyle]);
  useEffect(() => localStorage.setItem('cognix_accent', accentColor), [accentColor]);
  useEffect(() => localStorage.setItem('cognix_system_instruction', systemInstruction), [systemInstruction]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  // Sync active chat
  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  // Save messages to history
  useEffect(() => {
    if (messages.length > 0 && !activeChatId) {
       if (messages[0].parts[0]?.text) {
          const newId = Date.now().toString();
          const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
          const newSession: ChatSession = {
            id: newId,
            title: firstUserText.slice(0, 20) + (firstUserText.length > 20 ? '...' : ''),
            messages: messages
          };
          setChatHistory(prev => [newSession, ...prev]);
          setActiveChatId(newId);
       }
    } else if (activeChatId && messages.length > 0) {
       setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
    }
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleOpenInvite = () => {
    setInviteLink(`https://cognix.ai/join/${Math.random().toString(36).slice(2,8)}`);
    setIsInviteOpen(true);
    setIsCopied(false);
  };

  // Dynamic Background Wrapper
  const wrapperClass = useMemo(() => {
      switch(uiStyle) {
          case 'modern': return "bg-[#F3F4F6] dark:bg-[#18181B]"; // Soft Clay
          case 'retro': return "bg-[#008080]"; // Windows Teal
          case 'brutal': return "bg-white dark:bg-black"; // Stark
          case 'glass': return "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-gray-900 via-[#1a1a2e] to-black"; // Deep Space
          default: return "bg-gray-50";
      }
  }, [uiStyle]);

  return (
    <div className={`flex h-[100dvh] overflow-hidden transition-colors duration-500 font-sans ${wrapperClass} ${isDarkMode ? 'dark' : ''}`}>

      {/* Invite Modal */}
      {isInviteOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4" onClick={() => setIsInviteOpen(false)}>
            <div className={`w-full max-w-md bg-white dark:bg-gray-800 p-6 shadow-2xl animate-fade-in-up
                ${uiStyle === 'modern' ? 'rounded-[2rem]' : ''}
                ${uiStyle === 'retro' ? 'border-2 border-white outline outline-2 outline-gray-400 bg-[#c0c0c0] text-black' : ''}
                ${uiStyle === 'brutal' ? 'border-4 border-black shadow-[8px_8px_0_0_#000]' : ''}
            `} onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-bold">Invite to Session</h3>
                    <button onClick={() => setIsInviteOpen(false)}><XIcon className="w-6 h-6"/></button>
                </div>
                <div className={`flex gap-2 p-2 ${uiStyle === 'modern' ? 'bg-gray-100 dark:bg-gray-700 rounded-xl' : 'border-2 border-gray-400 bg-white'}`}>
                    <input readOnly value={inviteLink} className="flex-1 bg-transparent outline-none px-2 text-sm" />
                    <button onClick={() => { navigator.clipboard.writeText(inviteLink); setIsCopied(true); }} className={`${activeTheme.primary} text-white px-3 py-1.5 text-sm font-bold ${uiStyle === 'modern' ? 'rounded-lg' : ''}`}>
                        {isCopied ? 'COPIED' : 'COPY'}
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Sidebar - Structure varies by theme */}
      <div className={`
        fixed md:static inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out h-full shrink-0 flex
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
        ${isDesktopSidebarOpen ? 'md:w-72' : 'md:w-0'}
        ${uiStyle === 'modern' ? 'p-4 pr-0' : ''}
        ${uiStyle === 'glass' ? 'bg-black/20 backdrop-blur-md border-r border-white/10' : ''}
      `}>
         <div className={`w-full h-full flex flex-col overflow-hidden
            ${uiStyle === 'modern' ? 'bg-white dark:bg-[#27272a] rounded-[2rem] shadow-clay dark:shadow-clay-dark' : ''}
            ${uiStyle === 'retro' ? 'bg-[#c0c0c0] border-r-2 border-white outline outline-2 outline-gray-500' : ''}
            ${uiStyle === 'brutal' ? 'bg-white dark:bg-zinc-900 border-r-4 border-black' : ''}
         `}>
             <Sidebar 
                chatHistory={chatHistory}
                activeChatId={activeChatId}
                mode={mode}
                onSetMode={(m) => { setMode(m); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
                onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
                onNewChat={handleNewChat}
                onDeleteChat={(id) => {
                    setChatHistory(h => h.filter(c => c.id !== id));
                    if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
                }}
                onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
                onOpenSettings={() => setIsSettingsOpen(true)}
                uiStyle={uiStyle}
                theme={activeTheme}
             />
         </div>
      </div>

      {/* Mobile Overlay */}
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsSidebarOpen(false)} />}

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-full min-w-0 relative">

        {/* Header */}
        <header className={`h-16 flex items-center justify-between px-6 shrink-0 z-30
            ${uiStyle === 'retro' ? 'bg-[#000080] text-white px-2 m-2 mb-0 border-2 border-white shadow-[2px_2px_0_0_#000]' : ''}
            ${uiStyle === 'brutal' ? 'border-b-4 border-black bg-yellow-300' : ''}
            ${uiStyle === 'glass' ? 'bg-transparent text-white' : ''}
        `}>
             <div className="flex items-center gap-3">
                <button onClick={() => window.innerWidth >= 768 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)}>
                    <MenuIcon className={`w-6 h-6 ${uiStyle === 'retro' ? 'text-white' : 'text-current'}`}/>
                </button>
                <h1 className={`font-bold truncate ${uiStyle === 'retro' ? 'font-pixel text-xs' : 'text-lg'}`}>
                    {mode === 'live' ? 'LIVE SESSION' : (currentChat?.title || 'COGNIX AI')}
                </h1>
             </div>

             {mode === 'chat' && (
                 <button onClick={handleOpenInvite} className={`flex items-center gap-2 px-3 py-1.5 text-sm font-bold transition-all
                    ${uiStyle === 'modern' ? 'bg-gray-100 dark:bg-gray-800 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700' : ''}
                    ${uiStyle === 'retro' ? 'bg-[#c0c0c0] text-black border-2 border-white border-b-black border-r-black active:border-t-black active:border-l-black' : ''}
                    ${uiStyle === 'brutal' ? 'bg-white border-2 border-black shadow-[2px_2px_0_0_#000] hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-none' : ''}
                    ${uiStyle === 'glass' ? 'bg-white/10 hover:bg-white/20 rounded-full border border-white/20' : ''}
                 `}>
                    <UsersIcon className="w-4 h-4"/>
                    <span className="hidden sm:inline">INVITE</span>
                 </button>
             )}
        </header>

        {/* Workspace */}
        <main className={`flex-1 relative overflow-hidden flex flex-col
            ${uiStyle === 'modern' ? 'm-4 rounded-[2rem] bg-white/50 dark:bg-black/20' : ''}
            ${uiStyle === 'retro' ? 'm-2 mt-0 bg-white border-2 border-gray-500 inset-shadow' : ''}
        `}>
             {mode === 'chat' && (
                <ChatView 
                    messages={messages} 
                    setMessages={setMessages}
                    uiStyle={uiStyle}
                    theme={activeTheme}
                    fontSize={fontSize}
                    systemInstruction={systemInstruction}
                />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
        </main>

      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle}
        setUiStyle={setUiStyle}
        accentColor={accentColor}
        setAccentColor={setAccentColor}
        fontSize={fontSize}
        setFontSize={setFontSize}
        isDarkMode={isDarkMode}
        setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
        systemInstruction={systemInstruction}
        setSystemInstruction={setSystemInstruction}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, UIStyle, ThemeColors } from '../types';
import { NewChatIcon, TrashIcon, PencilIcon, MicrophoneIcon, BotIcon, SettingsIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  onRenameChat: (id: string, newTitle: string) => void;
  onOpenSettings: () => void;
  uiStyle: UIStyle;
  theme: ThemeColors;
}

export const Sidebar: React.FC<SidebarProps> = ({
  chatHistory,
  activeChatId,
  mode,
  onSetMode,
  onSelectChat,
  onNewChat,
  onDeleteChat,
  onRenameChat,
  onOpenSettings,
  uiStyle,
  theme,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) onRenameChat(editingChatId, newTitle.trim());
    setEditingChatId(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleRename();
    else if (e.key === 'Escape') setEditingChatId(null);
  };

  // --- RETRO SIDEBAR (System 95) ---
  if (uiStyle === 'retro') {
      return (
          <div className="flex flex-col h-full text-black font-pixel text-xs">
              <div className="p-2 border-b-2 border-gray-400 mb-2">
                  <div className="flex items-center gap-2 mb-4">
                       <BotIcon className="w-6 h-6"/>
                       <span className="font-bold text-sm">Cognix.exe</span>
                  </div>
                  <button onClick={onNewChat} className="w-full flex items-center justify-center gap-2 bg-[#c0c0c0] border-t-2 border-l-2 border-white border-b-2 border-r-2 border-black active:border-t-black active:border-l-black active:border-b-white active:border-r-white py-1">
                      <NewChatIcon className="w-4 h-4"/> NEW_CHAT
                  </button>
              </div>
              <div className="flex-1 overflow-y-auto px-2 retro-scroll">
                  {chatHistory.map(chat => (
                      <div key={chat.id} onClick={() => onSelectChat(chat.id)} 
                           className={`flex items-center gap-2 p-1 cursor-pointer mb-1 ${activeChatId === chat.id ? 'bg-[#000080] text-white' : 'hover:bg-gray-300'}`}>
                           <span>{activeChatId === chat.id ? '📂' : '📁'}</span>
                           <span className="truncate">{chat.title}</span>
                      </div>
                  ))}
              </div>
              <div className="p-2 border-t-2 border-white">
                   <button onClick={onOpenSettings} className="w-full mb-2 bg-[#c0c0c0] border-2 border-white border-b-black border-r-black p-1 text-center">Settings</button>
                   <button onClick={() => onSetMode('live')} className="w-full bg-[#c0c0c0] border-2 border-white border-b-black border-r-black p-1 text-center flex justify-center gap-2">
                       <MicrophoneIcon className="w-3 h-3"/> Live
                   </button>
              </div>
          </div>
      );
  }

  // --- BRUTAL SIDEBAR (Bauhaus) ---
  if (uiStyle === 'brutal') {
      return (
        <div className="flex flex-col h-full bg-white dark:bg-zinc-900 text-black dark:text-white">
            <div className="p-4 border-b-4 border-black">
                <div className="flex items-center gap-2 mb-4">
                    <div className="w-8 h-8 bg-blue-600 rounded-full border-2 border-black flex items-center justify-center text-white"><BotIcon className="w-5 h-5"/></div>
                    <h1 className="text-2xl font-black uppercase tracking-tighter">COGNIX</h1>
                </div>
                <button onClick={onNewChat} className="w-full bg-red-500 text-white font-bold uppercase py-3 border-2 border-black shadow-[4px_4px_0_0_#000] hover:translate-x-[2px] hover:translate-y-[2px] hover:shadow-none transition-all">
                    Start New Chat
                </button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-3">
                {chatHistory.map(chat => (
                    <div key={chat.id} onClick={() => onSelectChat(chat.id)} className={`p-3 font-bold border-2 border-black cursor-pointer transition-all ${activeChatId === chat.id ? 'bg-yellow-400 shadow-[4px_4px_0_0_#000]' : 'hover:bg-gray-100'}`}>
                        {chat.title.toUpperCase()}
                    </div>
                ))}
            </div>
            <div className="p-4 border-t-4 border-black bg-blue-100">
                <button onClick={onOpenSettings} className="w-full flex items-center justify-center gap-2 font-bold uppercase hover:underline">
                    <SettingsIcon className="w-5 h-5"/> PREFERENCES
