import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize } from '../types';
import { ai } from '../services/gemini';
import { BotIcon, SendIcon, SearchIcon, UserIcon, ImageIcon, XIcon, SpeakerIcon, CopyIcon, EditIcon, CheckIcon } from './Icons';
import { Modality } from "@google/genai";

const speakText = async (text: string) => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: text.slice(0, 400) }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
            },
        });
        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) new Audio(`data:audio/mp3;base64,${base64Audio}`).play();
    } catch (e) { console.error("TTS Error:", e); }
};

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
}

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, uiStyle, theme, fontSize, systemInstruction }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
  }, [messages, isLoading, selectedImage]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64Data = (reader.result as string).split(',')[1];
            setSelectedImage({ data: base64Data, mimeType: file.type });
        };
        reader.readAsDataURL(file);
    }
  };

  const handleSendMessage = useCallback(async () => {
    const textInput = input.trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }] };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      let stream = await ai.models.generateContentStream({
          model: 'gemini-2.5-flash',
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { systemInstruction, tools: [{ googleSearch: {} }] },
      });

      let fullText = '';
      const collectedSearchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: fullText }] } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            collectedSearchResults.push(...results);
        }
      }

      if (collectedSearchResults.length > 0) {
        const unique = Array.from(new Map(collectedSearchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `Error: ${error instanceof Error ? error.message : "Unknown"}` }] } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction]);

  const getFontSizeClass = () => {
      switch(fontSize) {
          case 'small': return 'text-sm';
          case 'large': return 'text-lg';
          default: return 'text-base';
      }
  };

  // --- RETRO THEME ---
  if (uiStyle === 'retro') {
      return (
          <div className="flex flex-col h-full bg-[#008080] font-pixel text-xs p-1">
             <div className="flex-1 bg-white border-2 border-gray-500 overflow-y-auto p-4 retro-scroll" ref={chatContainerRef}>
                {messages.map((msg) => (
                    <div key={msg.id} className={`mb-4 ${msg.role === 'user' ? 'text-blue-800 text-right' : 'text-black'}`}>
                        <div className="font-bold mb-1 uppercase">[{msg.role === 'user' ? 'User' : 'System'}]</div>
                        <div className="whitespace-pre-wrap leading-relaxed">
                            {msg.parts.map((p, i) => (
                                <div key={i}>
                                    {p.inlineData && <div className="border border-black p-1 inline-block bg-gray-200">[IMG]</div>}
                                    {p.text}
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
                {isLoading && <div className="text-gray-500">Processing...</div>}
             </div>
             <div className="h-12 mt-1 bg-[#c0c0c0] border-t-2 border-white flex items-center p-1 gap-2">
                 <textarea value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && handleSendMessage()} className="flex-1 h-full border-2 border-gray-500 p-1 outline-none resize-none font-pixel" />
                 <button onClick={handleSendMessage} className="bg-[#c0c0c0] border-2 border-white border-b-black border-r-black px-2 h-full active:border-t-black active:border-l-black">SEND</button>
             </div>
          </div>
      );
  }

  // --- BRUTAL THEME ---
  if (uiStyle === 'brutal') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-zinc-900 font-bold p-4">
              <div className="flex-1 overflow-y-auto space-y-6 no-scrollbar pb-24" ref={chatContainerRef}>
                  {messages.map((msg, idx) => (
                      <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                          <div className={`max-w-[80%] border-4 border-black p-4 shadow-[8px_8px_0_0_#000] ${msg.role === 'user' ? 'bg-blue-400 text-white' : 'bg-white text-black'}`}>
                              <div className="text-xs uppercase border-b-4 border-black pb-2 mb-2">{msg.role}</div>
                              {msg.parts.map((p, i) => (
                                  <div key={i} className="whitespace-pre-wrap">{p.text}</div>
                              ))}
                          </div>
                      </div>
                  ))}
              </div>
              <div className="absolute bottom-4 left-4 right-4 bg-yellow-300 border-4 border-black p-2 flex gap-2 shadow-[8px_8px_0_0_#000]">
                  <textarea value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && !e.shiftKey && handleSendMessage()} className="flex-1 bg-white border-4 border-black p-2 font-bold outline-none resize-none h-12" placeholder="TYPE HERE..." />
                  <button onClick={handleSendMessage} className="bg-black text-white px-6 font-black uppercase hover:bg-gray-800">SEND</button>
              </div>
          </div>
      );
  }

  // --- MODERN (SOFT CLAY) & GLASS (HOLOGRAPHIC) ---
  const isGlass = uiStyle === 'glass';

  return (
    <div className="flex flex-col h-full relative">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 sm:px-12 pb-40 pt-8 no-scrollbar scroll-smooth">
        {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center min-h-[60vh] animate-fade-in text-center">
                 <div className={`w-24 h-24 mb-6 rounded-[2rem] flex items-center justify-center ${isGlass ? 'bg-white/10 backdrop-blur-xl border border-white/20' : 'bg-white shadow-clay text-blue-500'}`}>
                     <BotIcon className={`w-12 h-12 ${isGlass ? 'text-white' : ''}`}/>
                 </div>
                 <h1 className={`text-3xl font-bold mb-2 ${isGlass ? 'text-white' : 'text-gray-900 dark:text-white'}`}>How can I help?</h1>
            </div>
        ) : (
            <div className="max-w-4xl mx-auto space-y-10">
                {messages.map((msg, idx) => (
                    <div key={msg.id} className={`flex gap-6 animate-fade-in-up ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        <div className={`w-10 h-10 shrink-0 rounded-xl flex items-center justify-center ${msg.role === 'user' ? 'bg-gray-200 dark:bg-zinc-700' : `${theme.primary} text-white shadow-lg`}`}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5 opacity-50"/> : <BotIcon className="w-6 h-6"/>}
                        </div>
                        <div className={`flex flex-col gap-2 max-w-[80%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative p-6 rounded-3xl leading-relaxed ${getFontSizeClass()} transition-all
                                     ${msg.role === 'user' 
                                         ? (isGlass ? 'bg-white/20 backdrop-blur-md text-white' : `bg-white dark:bg-zinc-800 shadow-clay dark:shadow-clay-dark text-gray-800 dark:text-gray-100`)
                                         : (isGlass ? 'text-white/90' : 'text-gray-800 dark:text-gray-200 pl-0')
                                     }
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-2xl mb-4 shadow-md max-h-80" alt="Upload"/>}
                                     <div className="whitespace-pre-wrap markdown-body">{part.text}</div>

                                     {/* Actions */}
                                     {msg.role === 'model' && (
                                         <div className="flex gap-2 mt-4 opacity-0 group-hover:opacity-100 transition-opacity">
                                             <button onClick={() => speakText(part.text || '')}><SpeakerIcon className="w-4 h-4 opacity-50 hover:opacity-100"/></button>
                                             <button onClick={() => navigator.clipboard.writeText(part.text || '')}><CopyIcon className="w-4 h-4 opacity-50 hover:opacity-100"/></button>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
            </div>
        )}
      </div>

      {/* Input Area */}
      <div className="absolute bottom-8 left-0 right-0 px-4 z-20 flex justify-center pointer-events-none">
          <div className={`w-full max-w-3xl pointer-events-auto flex items-end gap-2 p-2 pl-4 transition-all duration-300 rounded-[2.5rem]
               ${isGlass 
                   ? 'bg-black/40 backdrop-blur-xl border border-white/20 shadow-2xl' 
                   : 'bg-white dark:bg-[#27272a] shadow-clay dark:shadow-clay-dark'}
          `}>
               <input type="file" ref={fileInputRef} onChange={handleImageSelect} accept="image/*" className="hidden" />
               <button onClick={() => fileInputRef.current?.click()} className={`p-3 mb-1 rounded-full transition-colors ${isGlass ? 'text-white/70 hover:bg-white/10' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-zinc-700'}`}>
                   <ImageIcon className="w-6 h-6"/>
               </button>
               <textarea
                   ref={textareaRef}
                   value={input}
                   onChange={e => setInput(e.target.value)}
                   onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                   placeholder="Ask anything..."
                   className={`flex-1 bg-transparent border-none outline-none resize-none py-4 max-h-32 ${getFontSizeClass()} ${isGlass ? 'text-white placeholder-white/40' : 'text-gray-900 dark:text-white'}`}
                   rows={1}
               />
               <button onClick={handleSendMessage} disabled={isLoading || (!input && !selectedImage)} className={`p-3 m-1.5 rounded-full text-white shadow-lg transition-transform hover:scale-105 active:scale-95 disabled:opacity-50 disabled:scale-100 ${theme.primary}`}>
                   <SendIcon className="w-5 h-5"/>
               </button>
          </div>
      </div>
    </div>
  );
};

