    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-500', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-900/20', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-500', ring: 'focus:ring-emerald-500', gradient: 'bg-gradient-to-r from-emerald-900 to-black' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-500', textDark: 'text-rose-400', bgSoft: 'bg-rose-900/20', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-500', ring: 'focus:ring-rose-500', gradient: 'bg-gradient-to-r from-rose-900 to-black' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-500', textDark: 'text-amber-400', bgSoft: 'bg-amber-900/20', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-500', ring: 'focus:ring-amber-500', gradient: 'bg-gradient-to-r from-amber-900 to-black' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [accentColor, setAccentColor] = useState<AccentColor>('amber'); // Gold default for Neo-Classic
  const [fontSize, setFontSize] = useState<FontSize>('normal');
  const [systemInstruction, setSystemInstruction] = useState("You are Cognix AI, a futuristic archive assistant. Be precise and elegant.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);

  const [isDarkMode, setIsDarkMode] = useState(true); // Default dark for Neo-Classic
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);

  const [isInviteOpen, setIsInviteOpen] = useState(false);
  const [inviteLink, setInviteLink] = useState('');
  const [isCopied, setIsCopied] = useState(false);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_chat_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    const savedStyle = localStorage.getItem('cognix_style') as UIStyle;
    if (savedStyle) setUiStyle(savedStyle);

    const savedAccent = localStorage.getItem('cognix_accent') as AccentColor;
    if (savedAccent) setAccentColor(savedAccent);

    // Default to dark mode for Neo-Classic
    document.documentElement.classList.add('dark');
  }, []);

  useEffect(() => localStorage.setItem('cognix_chat_history', JSON.stringify(chatHistory)), [chatHistory]);
  useEffect(() => localStorage.setItem('cognix_style', uiStyle), [uiStyle]);
  useEffect(() => localStorage.setItem('cognix_accent', accentColor), [accentColor]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  useEffect(() => {
    if (messages.length > 0 && !activeChatId) {
       if (messages[0].parts[0]?.text) {
          const newId = Date.now().toString();
          const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Log';
          const newSession: ChatSession = {
            id: newId,
            title: firstUserText.slice(0, 20),
            messages: messages
          };
          setChatHistory(prev => [newSession, ...prev]);
          setActiveChatId(newId);
       }
    } else if (activeChatId && messages.length > 0) {
       setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
    }
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleOpenInvite = () => {
    setInviteLink(`https://cognix.ai/uplink/${Math.random().toString(36).slice(2,8)}`);
    setIsInviteOpen(true);
    setIsCopied(false);
  };

  // Neo-Classic Wrapper
  const wrapperClass = useMemo(() => {
      switch(uiStyle) {
          case 'modern': return "bg-stardust text-gray-100"; // Neo-Classic Default
          case 'retro': return "bg-[#008080]"; 
          case 'brutal': return "bg-white dark:bg-black"; 
          case 'glass': return "bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-gray-900 via-[#1a1a2e] to-black"; 
          default: return "bg-stardust";
      }
  }, [uiStyle]);

  return (
    <div className={`flex h-[100dvh] overflow-hidden transition-colors duration-500 font-sans ${wrapperClass} dark`}>

      {/* Neo-Classic Frame Border for Default Theme */}
      {uiStyle === 'modern' && (
          <div className="absolute inset-0 pointer-events-none z-[60] border-[1px] border-white/5 m-2 rounded-sm"></div>
      )}

      {/* Invite Modal */}
      {isInviteOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-md p-4" onClick={() => setIsInviteOpen(false)}>
            <div className={`w-full max-w-md p-0.5 bg-gradient-to-b from-gold-500 to-transparent animate-fade-in-up
                ${uiStyle === 'modern' ? 'shadow-glow-gold' : ''}
            `} onClick={e => e.stopPropagation()}>
                <div className="bg-obsidian p-8 border border-white/10 relative">
                    <h3 className="text-xl font-display font-bold text-gold-500 mb-6 tracking-widest uppercase text-center border-b border-white/10 pb-4">Secure Uplink</h3>
                    <div className="flex gap-2 p-1 border border-white/20 bg-black">
                        <input readOnly value={inviteLink} className="flex-1 bg-transparent outline-none px-4 text-sm font-mono text-cyan-400" />
                        <button onClick={() => { navigator.clipboard.writeText(inviteLink); setIsCopied(true); }} className="text-obsidian bg-gold-500 hover:bg-gold-400 px-4 py-2 text-xs font-bold uppercase tracking-wider transition-colors">
                            {isCopied ? 'Copied' : 'Copy'}
                        </button>
                    </div>
                    <button onClick={() => setIsInviteOpen(false)} className="absolute top-2 right-4 text-white/50 hover:text-white">&times;</button>
                </div>
            </div>
        </div>
      )}

      {/* Sidebar */}
      <div className={`
        fixed md:static inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out h-full shrink-0 flex
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
        ${isDesktopSidebarOpen ? 'md:w-72' : 'md:w-0'}
        ${uiStyle === 'modern' ? 'md:border-r border-white/10 bg-obsidian/90 backdrop-blur-lg' : ''}
        ${uiStyle === 'glass' ? 'bg-black/20 backdrop-blur-md border-r border-white/10' : ''}
      `}>
         <Sidebar 
            chatHistory={chatHistory}
            activeChatId={activeChatId}
            mode={mode}
            onSetMode={(m) => { setMode(m); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
            onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
            onNewChat={handleNewChat}
            onDeleteChat={(id) => {
                setChatHistory(h => h.filter(c => c.id !== id));
                if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
            }}
            onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
            onOpenSettings={() => setIsSettingsOpen(true)}
            uiStyle={uiStyle}
            theme={activeTheme}
         />
      </div>

      {/* Mobile Overlay */}
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsSidebarOpen(false)} />}

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-full min-w-0 relative">

        {/* Header */}
        <header className={`h-16 flex items-center justify-between px-6 shrink-0 z-30
            ${uiStyle === 'modern' ? 'border-b border-white/5 bg-obsidian/50 backdrop-blur-sm' : ''}
            ${uiStyle === 'retro' ? 'bg-[#000080] text-white px-2 m-2 mb-0 border-2 border-white' : ''}
            ${uiStyle === 'brutal' ? 'border-b-4 border-black bg-yellow-300' : ''}
            ${uiStyle === 'glass' ? 'bg-transparent text-white' : ''}
        `}>
             <div className="flex items-center gap-4">
                <button onClick={() => window.innerWidth >= 768 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)} 
                    className="hover:text-gold-500 transition-colors">
                    <MenuIcon className={`w-6 h-6 ${uiStyle === 'retro' ? 'text-white' : 'text-current'}`}/>
                </button>
                <div className="flex flex-col">
                    <h1 className={`font-bold tracking-widest uppercase
                        ${uiStyle === 'modern' ? 'font-display text-gold-500 text-lg' : ''}
                        ${uiStyle === 'retro' ? 'font-pixel text-xs' : ''}
                    `}>
                        {mode === 'live' ? 'VOICE UPLINK' : (currentChat?.title || 'COGNIX TERMINAL')}
                    </h1>
                    {uiStyle === 'modern' && <span className="text-[10px] font-mono text-white/30 tracking-[0.2em]">{new Date().toLocaleDateString().toUpperCase()}</span>}
                </div>
             </div>

             {mode === 'chat' && (
                 <button onClick={handleOpenInvite} className={`flex items-center gap-2 px-4 py-1.5 text-xs font-bold uppercase tracking-widest transition-all
                    ${uiStyle === 'modern' ? 'border border-gold-500/30 text-gold-500 hover:bg-gold-500/10' : ''}
                    ${uiStyle === 'retro' ? 'bg-[#c0c0c0] text-black border-2 border-white border-b-black border-r-black' : ''}
                    ${uiStyle === 'brutal' ? 'bg-white border-2 border-black shadow-[2px_2px_0_0_#000]' : ''}
                    ${uiStyle === 'glass' ? 'bg-white/10 hover:bg-white/20 rounded-full border border-white/20' : ''}
                 `}>
                    <UsersIcon className="w-4 h-4"/>
                    <span className="hidden sm:inline">Connect</span>
                 </button>
             )}
        </header>

        {/* Workspace */}
        <main className={`flex-1 relative overflow-hidden flex flex-col
            ${uiStyle === 'modern' ? 'bg-transparent' : ''}
            ${uiStyle === 'retro' ? 'm-2 mt-0 bg-white border-2 border-gray-500 inset-shadow' : ''}
        `}>
             {mode === 'chat' && (
                <ChatView 
                    messages={messages} 
                    setMessages={setMessages}
                    uiStyle={uiStyle}
                    theme={activeTheme}
                    fontSize={fontSize}
                    systemInstruction={systemInstruction}
                />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle}
        setUiStyle={setUiStyle}
        accentColor={accentColor}
        setAccentColor={setAccentColor}
        fontSize={fontSize}
        setFontSize={setFontSize}
        isDarkMode={isDarkMode}
        setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
        systemInstruction={systemInstruction}
        setSystemInstruction={setSystemInstruction}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, UIStyle, ThemeColors } from '../types';
