                    <div key={chat.id} onClick={() => onSelectChat(chat.id)} className={`p-3 font-bold border-2 border-black cursor-pointer transition-all ${activeChatId === chat.id ? 'bg-yellow-400 shadow-[4px_4px_0_0_#000]' : 'hover:bg-gray-100'}`}>
                        {chat.title.toUpperCase()}
