  // --- FUTURISTIC CLASSIC (MODERN) & GLASS ---
  const isNeo = uiStyle === 'modern';

  return (
    <div className={`flex flex-col h-full ${uiStyle === 'glass' ? 'text-white' : 'text-gray-100'}`}>

      {/* Header */}
      <div className={`p-6 ${isNeo ? 'border-b border-white/5' : ''}`}>
        <div className="flex items-center gap-4 mb-8">
            <div className={`w-12 h-12 flex items-center justify-center 
                ${isNeo ? 'bg-black border border-gold-500 shadow-glow-gold' : 'bg-white/10 backdrop-blur-md border border-white/20 rounded-2xl'} 
            `}>
                <BotIcon className={`w-6 h-6 ${isNeo ? 'text-gold-500' : 'text-white'}`} />
            </div>
            <div>
                <h2 className={`text-xl font-bold tracking-widest uppercase ${isNeo ? 'font-display text-white' : ''}`}>Cognix</h2>
