                    : 'rounded-xl text-white/70 hover:bg-white/10 font-bold'}
                ${mode === 'live' ? (isNeo ? 'bg-cyan-900/20 border-cyan-500/50 shadow-[0_0_15px_rgba(0,255,255,0.1)]' : 'bg-white/20') : ''}
            `}
        >
            <MicrophoneIcon className="w-4 h-4" />
            Voice Uplink
        </button>
      </div>

      {/* List */}
      <div className="flex-1 overflow-y-auto px-4 pb-4 classic-scroll">
        <div className={`text-[10px] font-bold uppercase tracking-[0.2em] opacity-40 mb-4 px-2 mt-4 ${isNeo ? 'font-display text-white' : ''}`}>Archives</div>
        <div className="space-y-1">
            {chatHistory.map((chat) => (
            <div
                key={chat.id}
                onClick={() => { if(editingChatId !== chat.id) onSelectChat(chat.id); }}
                className={`group relative flex items-center justify-between px-4 py-3 cursor-pointer transition-all
                ${isNeo ? 'border-l-2 border-transparent hover:border-white/20 hover:bg-white/5' : 'rounded-xl hover:bg-white/5'}
