                        className="bg-transparent border-b border-gold-500 w-full outline-none text-xs font-mono text-gold-500"
                    />
                ) : (
                    <>
                    <span className={`truncate text-xs ${isNeo ? 'font-mono text-gray-300 group-hover:text-white' : 'opacity-90'}`}>{chat.title}</span>
                    <div className="hidden group-hover:flex items-center gap-1 absolute right-2 bg-black shadow-sm p-1">
                         <button onClick={(e) => { e.stopPropagation(); setEditingChatId(chat.id); setNewTitle(chat.title); }} className="p-1 hover:text-cyan-500"><PencilIcon className="w-3 h-3"/></button>
                         <button onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }} className="p-1 hover:text-red-500"><TrashIcon className="w-3 h-3"/></button>
