import React, { useState, useEffect, useMemo } from 'react';
import { ChatView } from './components/ChatView';
import { LiveView } from './components/LiveView';
import { Sidebar } from './components/Sidebar';
import { MenuIcon, UsersIcon } from './components/Icons';
import { SettingsModal } from './components/SettingsModal';
import { ai } from './services/gemini';
import type { ChatMessage, ChatSession, Mode, UIStyle, AccentColor, ThemeColors, FontSize } from './types';

const THEMES: Record<AccentColor, ThemeColors> = {
    blue: { primary: 'bg-blue-600', primaryHover: 'hover:bg-blue-700', text: 'text-blue-600', textDark: 'text-blue-400', bgSoft: 'bg-blue-50', darkBgSoft: 'dark:bg-blue-900/20', border: 'border-blue-600', ring: 'focus:ring-blue-600', gradient: 'bg-gradient-to-r from-blue-500 to-cyan-500' },
    violet: { primary: 'bg-violet-600', primaryHover: 'hover:bg-violet-700', text: 'text-violet-600', textDark: 'text-violet-400', bgSoft: 'bg-violet-50', darkBgSoft: 'dark:bg-violet-900/20', border: 'border-violet-600', ring: 'focus:ring-violet-600', gradient: 'bg-gradient-to-r from-violet-500 to-purple-500' },
    emerald: { primary: 'bg-emerald-600', primaryHover: 'hover:bg-emerald-700', text: 'text-emerald-600', textDark: 'text-emerald-400', bgSoft: 'bg-emerald-50', darkBgSoft: 'dark:bg-emerald-900/20', border: 'border-emerald-600', ring: 'focus:ring-emerald-600', gradient: 'bg-gradient-to-r from-emerald-500 to-teal-500' },
    rose: { primary: 'bg-rose-600', primaryHover: 'hover:bg-rose-700', text: 'text-rose-600', textDark: 'text-rose-400', bgSoft: 'bg-rose-50', darkBgSoft: 'dark:bg-rose-900/20', border: 'border-rose-600', ring: 'focus:ring-rose-600', gradient: 'bg-gradient-to-r from-rose-500 to-pink-500' },
    amber: { primary: 'bg-amber-600', primaryHover: 'hover:bg-amber-700', text: 'text-amber-600', textDark: 'text-amber-400', bgSoft: 'bg-amber-50', darkBgSoft: 'dark:bg-amber-900/20', border: 'border-amber-600', ring: 'focus:ring-amber-600', gradient: 'bg-gradient-to-r from-amber-500 to-orange-500' },
};

const App: React.FC = () => {
  const [mode, setMode] = useState<Mode>('chat');
  const [uiStyle, setUiStyle] = useState<UIStyle>('modern');
  const [accentColor, setAccentColor] = useState<AccentColor>('blue');
  const [fontSize, setFontSize] = useState<FontSize>('normal');
  const [systemInstruction, setSystemInstruction] = useState("You are Cognix AI, a helpful assistant.");

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDesktopSidebarOpen, setIsDesktopSidebarOpen] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatSession[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);

  useEffect(() => {
    const savedHistory = localStorage.getItem('cognix_chat_history');
    if (savedHistory) setChatHistory(JSON.parse(savedHistory));

    // Default to light mode for this specific design request
    const savedTheme = localStorage.getItem('cognix_theme');
    if (savedTheme === 'dark') {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  useEffect(() => localStorage.setItem('cognix_chat_history', JSON.stringify(chatHistory)), [chatHistory]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('cognix_theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('cognix_theme', 'light');
    }
  }, [isDarkMode]);

  const currentChat = useMemo(() => chatHistory.find(c => c.id === activeChatId), [chatHistory, activeChatId]);
  const activeTheme = useMemo(() => THEMES[accentColor], [accentColor]);

  useEffect(() => {
    setMessages(currentChat ? currentChat.messages : []);
  }, [currentChat?.id]);

  useEffect(() => {
    if (messages.length > 0 && !activeChatId) {
       if (messages[0].parts[0]?.text) {
          const newId = Date.now().toString();
          const firstUserText = messages[0].parts.find(p => p.text)?.text || 'New Chat';
          const newSession: ChatSession = {
            id: newId,
            title: firstUserText.slice(0, 30),
            messages: messages
          };
          setChatHistory(prev => [newSession, ...prev]);
          setActiveChatId(newId);
       }
    } else if (activeChatId && messages.length > 0) {
       setChatHistory(prev => prev.map(session => session.id === activeChatId ? { ...session, messages } : session));
    }
  }, [messages, activeChatId]);

  const handleNewChat = () => {
    setActiveChatId(null);
    setMessages([]);
    setMode('chat');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  return (
    <div className={`flex h-[100dvh] overflow-hidden bg-white dark:bg-gray-900 text-gray-900 dark:text-gray-100 transition-colors duration-300 font-sans`}>

      {/* Sidebar */}
      <div className={`
        fixed md:static inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out h-full shrink-0 flex border-r border-gray-100 dark:border-gray-800 bg-white dark:bg-gray-900
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
        ${isDesktopSidebarOpen ? 'md:w-[280px]' : 'md:w-0'}
      `}>
         <div className="w-full h-full overflow-hidden">
             <Sidebar 
                chatHistory={chatHistory}
                activeChatId={activeChatId}
                mode={mode}
                onSetMode={(m) => { setMode(m); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
                onSelectChat={(id) => { setActiveChatId(id); setMode('chat'); if(window.innerWidth < 768) setIsSidebarOpen(false); }}
                onNewChat={handleNewChat}
                onDeleteChat={(id) => {
                    setChatHistory(h => h.filter(c => c.id !== id));
                    if (activeChatId === id) { setActiveChatId(null); setMessages([]); }
                }}
                onRenameChat={(id, t) => setChatHistory(h => h.map(c => c.id === id ? { ...c, title: t } : c))}
                onOpenSettings={() => setIsSettingsOpen(true)}
                uiStyle={uiStyle}
                theme={activeTheme}
             />
         </div>
      </div>

      {/* Mobile Overlay */}
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsSidebarOpen(false)} />}

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-full min-w-0 bg-white dark:bg-gray-900 relative">

        {/* Header */}
        <header className="h-16 flex items-center justify-between px-4 shrink-0 bg-white dark:bg-gray-900 z-30">
             <div className="flex items-center gap-3">
                <button 
                    onClick={() => window.innerWidth >= 768 ? setIsDesktopSidebarOpen(!isDesktopSidebarOpen) : setIsSidebarOpen(!isSidebarOpen)}
                    className="p-2 text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
                >
                    <MenuIcon className="w-5 h-5"/>
                </button>
                <h1 className="text-lg font-medium text-gray-800 dark:text-gray-100">
                    {mode === 'live' ? 'Live Conversation' : (currentChat?.title || 'New Chat')}
                </h1>
             </div>

             <div className="flex items-center gap-2">
                 <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors">
                     {isDarkMode ? (
                         <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M12 3v2.25m6.364.386l-1.591 1.591M21 12h-2.25m-.386 6.364l-1.591-1.591M12 18.75V21m-4.773-4.227l-1.591 1.591M5.25 12H3m4.227-4.773L5.636 5.636M15.75 12a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0z" /></svg>
                     ) : (
                         <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M21.752 15.002A9.718 9.718 0 0118 15.75c-5.385 0-9.75-4.365-9.75-9.75 0-1.33.266-2.597.748-3.752A9.753 9.753 0 003 11.25C3 16.635 7.365 21 12.75 21a9.753 9.753 0 009.002-5.998z" /></svg>
                     )}
                 </button>
                 <button onClick={() => setIsSettingsOpen(true)} className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M9.879 7.519c1.171-1.025 3.071-1.025 4.242 0 1.172 1.025 1.172 2.687 0 3.712-.203.179-.43.326-.67.442-.745.361-1.45.999-1.45 1.827v.75M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-9 5.25h.008v.008H12v-.008z" /></svg>
                 </button>
             </div>
        </header>

        {/* Workspace */}
        <main className="flex-1 relative overflow-hidden flex flex-col">
             {mode === 'chat' && (
                <ChatView 
                    messages={messages} 
                    setMessages={setMessages}
                    uiStyle={uiStyle}
                    theme={activeTheme}
                    fontSize={fontSize}
                    systemInstruction={systemInstruction}
                />
            )}
            {mode === 'live' && <LiveView theme={activeTheme} />}
        </main>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        uiStyle={uiStyle}
        setUiStyle={setUiStyle}
        accentColor={accentColor}
        setAccentColor={setAccentColor}
        fontSize={fontSize}
        setFontSize={setFontSize}
        isDarkMode={isDarkMode}
        setIsDarkMode={setIsDarkMode}
        onClearHistory={() => { setChatHistory([]); setMessages([]); setActiveChatId(null); setIsSettingsOpen(false); }}
        systemInstruction={systemInstruction}
        setSystemInstruction={setSystemInstruction}
      />
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect } from 'react';
import type { ChatSession, Mode, UIStyle, ThemeColors } from '../types';
import { NewChatIcon, TrashIcon, PencilIcon, MicrophoneIcon, BotIcon, SettingsIcon } from './Icons';

interface SidebarProps {
  chatHistory: ChatSession[];
  activeChatId: string | null;
  mode: Mode;
  onSetMode: (mode: Mode) => void;
  onSelectChat: (id: string) => void;
  onNewChat: () => void;
  onDeleteChat: (id: string) => void;
  onRenameChat: (id: string, newTitle: string) => void;
  onOpenSettings: () => void;
  uiStyle: UIStyle;
  theme: ThemeColors;
}

export const Sidebar: React.FC<SidebarProps> = ({
  chatHistory,
  activeChatId,
  mode,
  onSetMode,
  onSelectChat,
  onNewChat,
  onDeleteChat,
  onRenameChat,
  onOpenSettings,
  uiStyle,
  theme,
}) => {
  const [editingChatId, setEditingChatId] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editingChatId && inputRef.current) {
        inputRef.current.focus();
        inputRef.current.select();
    }
  }, [editingChatId]);

  const handleRename = () => {
    if (editingChatId && newTitle.trim()) onRenameChat(editingChatId, newTitle.trim());
    setEditingChatId(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleRename();
    else if (e.key === 'Escape') setEditingChatId(null);
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-gray-900 text-gray-700 dark:text-gray-300">

      {/* Header Area */}
      <div className="p-5 pb-0">
        <div className="flex items-center gap-3 mb-6">
            <div className="w-10 h-10 flex items-center justify-center bg-gradient-to-br from-blue-500 to-cyan-400 rounded-xl shadow-md">
                <BotIcon className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-xl font-bold text-gray-900 dark:text-white tracking-tight">Cognix</h1>
        </div>

        <button
          onClick={onNewChat}
          className="w-full flex items-center justify-center gap-2 py-3 bg-[#0f172a] hover:bg-[#1e293b] text-white rounded-lg font-medium transition-colors shadow-sm"
        >
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5">
             <path d="M10.75 4.75a.75.75 0 00-1.5 0v4.5h-4.5a.75.75 0 000 1.5h4.5v4.5a.75.75 0 001.5 0v-4.5h4.5a.75.75 0 000-1.5h-4.5v-4.5z" />
          </svg>
          <span>New Chat</span>
        </button>
      </div>

      {/* Nav Links */}
      <div className="px-3 mt-4 mb-2">
        <button
            onClick={() => onSetMode('live')}
            className={`w-full flex items-center gap-3 px-3 py-3 rounded-lg transition-colors
                ${mode === 'live' 
                    ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400 font-medium' 
                    : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800'}
            `}
        >
            <MicrophoneIcon className="w-5 h-5" />
            <span className="text-sm">Live Conversation</span>
        </button>
      </div>

      {/* Recent Chats List */}
      <div className="flex-1 overflow-y-auto px-3 pb-4">
        <div className="px-3 mb-2 mt-4">
            <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">Recent Chats</span>
        </div>
        <div className="space-y-0.5">
            {chatHistory.map((chat) => (
            <div
                key={chat.id}
                onClick={() => { if(editingChatId !== chat.id) onSelectChat(chat.id); }}
                className={`group relative flex items-center justify-between px-3 py-2.5 cursor-pointer rounded-lg transition-colors
                ${activeChatId === chat.id && mode === 'chat'
                    ? 'bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-white font-medium'
                    : 'text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-800/50'}
                `}
            >
                {editingChatId === chat.id ? (
                    <input
                        ref={inputRef}
                        type="text"
                        value={newTitle}
                        onChange={(e) => setNewTitle(e.target.value)}
                        onBlur={handleRename}
                        onKeyDown={handleKeyDown}
                        className="bg-transparent border-b border-blue-500 w-full outline-none text-sm py-0.5"
                    />
                ) : (
                    <>
                    <span className="truncate text-sm">{chat.title}</span>
                    <div className="hidden group-hover:flex items-center gap-1 absolute right-2 bg-white dark:bg-gray-800 shadow-sm rounded border border-gray-100 dark:border-gray-700 p-0.5">
                         <button onClick={(e) => { e.stopPropagation(); setEditingChatId(chat.id); setNewTitle(chat.title); }} className="p-1 hover:text-blue-500 text-gray-400"><PencilIcon className="w-3.5 h-3.5"/></button>
                         <button onClick={(e) => { e.stopPropagation(); onDeleteChat(chat.id); }} className="p-1 hover:text-red-500 text-gray-400"><TrashIcon className="w-3.5 h-3.5"/></button>
                    </div>
                    </>
                )}
            </div>
            ))}
        </div>
      </div>

      {/* Profile/Footer Area */}
      <div className="p-4 border-t border-gray-100 dark:border-gray-800">
          <div className="flex items-center gap-3 px-2">
              <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center text-blue-600 dark:text-blue-400 font-bold text-xs">
                  SJ
              </div>
              <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-gray-900 dark:text-white truncate">Shashwat Ranjan Jha</p>
                  <p className="text-xs text-gray-400 truncate">Free Plan</p>
              </div>
          </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import type { ChatMessage, ChatPart, SearchResult, UIStyle, ThemeColors, FontSize } from '../types';
import { ai } from '../services/gemini';
import { BotIcon, SendIcon, UserIcon, ImageIcon, SpeakerIcon, CopyIcon } from './Icons';
import { Modality } from "@google/genai";

const speakText = async (text: string) => {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: text.slice(0, 400) }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
            },
        });
        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) new Audio(`data:audio/mp3;base64,${base64Audio}`).play();
    } catch (e) { console.error("TTS Error:", e); }
};

interface ChatViewProps {
  messages: ChatMessage[];
  setMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>;
  uiStyle: UIStyle;
  theme: ThemeColors;
  fontSize: FontSize;
  systemInstruction: string;
}

const SuggestionCard: React.FC<{ title: string; subtitle: string; onClick: () => void }> = ({ title, subtitle, onClick }) => (
    <button 
        onClick={onClick}
        className="text-left p-4 rounded-xl border border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors group h-full"
    >
        <div className="font-semibold text-gray-900 dark:text-gray-100 mb-1 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">{title}</div>
        <div className="text-sm text-gray-500 dark:text-gray-400">{subtitle}</div>
    </button>
);

export const ChatView: React.FC<ChatViewProps> = ({ messages, setMessages, uiStyle, theme, fontSize, systemInstruction }) => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<{ data: string; mimeType: string } | null>(null);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
  }, [messages, isLoading, selectedImage]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64Data = (reader.result as string).split(',')[1];
            setSelectedImage({ data: base64Data, mimeType: file.type });
        };
        reader.readAsDataURL(file);
    }
  };

  const handleSendMessage = useCallback(async (textOverride?: string) => {
    const textInput = (textOverride || input).trim();
    if ((!textInput && !selectedImage) || isLoading) return;

    const userMessageParts: ChatPart[] = [];
    if (selectedImage) userMessageParts.push({ inlineData: { mimeType: selectedImage.mimeType, data: selectedImage.data } });
    if (textInput) userMessageParts.push({ text: textInput });

    const userMessage: ChatMessage = { id: `msg-${Date.now()}`, role: 'user', parts: userMessageParts };
    const modelPlaceholder: ChatMessage = { id: `msg-${Date.now() + 1}`, role: 'model', parts: [{ text: '' }] };

    setMessages(prev => [...prev, userMessage, modelPlaceholder]);
    setInput(''); 
    setSelectedImage(null);
    setIsLoading(true);

    try {
      const history = messages.map(msg => ({
        role: msg.role,
        parts: msg.parts.map(p => {
            if (p.text) return { text: p.text };
            if (p.inlineData) return { inlineData: p.inlineData };
            return null;
        }).filter(Boolean) as any[]
      }));

      let stream = await ai.models.generateContentStream({
          model: 'gemini-2.5-flash',
          contents: [...history, { role: 'user', parts: userMessageParts as any }],
          config: { systemInstruction, tools: [{ googleSearch: {} }] },
      });

      let fullText = '';
      const collectedSearchResults: SearchResult[] = [];

      for await (const chunk of stream) {
        if(chunk.text) {
            fullText += chunk.text;
            setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: fullText }] } : m));
        }
        const chunks = chunk.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            const results = chunks.map((c: any) => c.web ? { ...c.web, type: 'web' } : null).filter(Boolean);
            collectedSearchResults.push(...results);
        }
      }

      if (collectedSearchResults.length > 0) {
        const unique = Array.from(new Map(collectedSearchResults.map(i => [i.uri, i])).values());
        setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ ...m.parts[0], searchResults: unique }] } : m));
      }
    } catch (error) {
      setMessages(prev => prev.map(m => m.id === modelPlaceholder.id ? { ...m, parts: [{ text: `Error: ${error instanceof Error ? error.message : "Unknown"}` }] } : m));
    } finally {
      setIsLoading(false);
    }
  }, [input, isLoading, messages, selectedImage, systemInstruction]);

  return (
    <div className="flex flex-col h-full relative">
      <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-4 pb-40 pt-8 no-scrollbar scroll-smooth">
        {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center min-h-[65vh] animate-fade-in px-4">
                 <div className="w-20 h-20 mb-6 bg-gradient-to-br from-blue-500 to-cyan-400 rounded-2xl shadow-lg flex items-center justify-center">
                     <BotIcon className="w-10 h-10 text-white"/>
                 </div>

                 <h1 className="text-4xl font-bold text-gray-900 dark:text-white mb-2 tracking-tight text-center">Hello, Friend</h1>
                 <p className="text-gray-400 dark:text-gray-500 mb-12 font-medium">Created by Shashwat Ranjan Jha</p>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-2xl">
                     <SuggestionCard 
                        title="Plan a trip" 
                        subtitle="to see the Northern Lights" 
                        onClick={() => handleSendMessage("Plan a trip to see the Northern Lights")} 
                     />
                     <SuggestionCard 
                        title="Analyze data" 
                        subtitle="using Python code execution" 
                        onClick={() => handleSendMessage("Analyze some data using Python")} 
                     />
                     <SuggestionCard 
                        title="Draft an email" 
                        subtitle="to request a project extension" 
                        onClick={() => handleSendMessage("Draft an email to request a project extension")} 
                     />
                     <SuggestionCard 
                        title="Write code" 
                        subtitle="for a Python countdown timer" 
                        onClick={() => handleSendMessage("Write code for a Python countdown timer")} 
                     />
                 </div>
            </div>
        ) : (
            <div className="max-w-3xl mx-auto space-y-6">
                {messages.map((msg, idx) => (
                    <div key={msg.id} className={`flex gap-4 animate-fade-in-up ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                        {/* Avatar */}
                        <div className={`w-8 h-8 shrink-0 rounded-full flex items-center justify-center 
                            ${msg.role === 'user' ? 'bg-gray-200 dark:bg-gray-700 text-gray-500' : 'bg-gradient-to-br from-blue-500 to-cyan-400 text-white shadow-sm'}
                        `}>
                             {msg.role === 'user' ? <UserIcon className="w-5 h-5"/> : <BotIcon className="w-5 h-5"/>}
                        </div>

                        {/* Content */}
                        <div className={`flex flex-col gap-1 max-w-[85%] ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                             <div className="font-semibold text-xs text-gray-900 dark:text-white ml-1">
                                {msg.role === 'user' ? 'You' : 'Cognix'}
                             </div>
                             {msg.parts.map((part, i) => (
                                 <div key={i} className={`relative leading-relaxed text-[15px]
                                     ${msg.role === 'user' 
                                         ? 'bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-gray-100 px-5 py-3 rounded-2xl rounded-tr-none' 
                                         : 'text-gray-800 dark:text-gray-200 px-1'}
                                 `}>
                                     {part.inlineData && <img src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} className="rounded-lg mb-3 max-h-80 shadow-sm border border-gray-100 dark:border-gray-700" alt="Upload"/>}
                                     <div className="whitespace-pre-wrap markdown-body">{part.text}</div>

                                     {msg.role === 'model' && (
                                         <div className="flex gap-2 mt-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                             <button onClick={() => speakText(part.text || '')} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-800 rounded text-gray-400 hover:text-gray-600"><SpeakerIcon className="w-4 h-4"/></button>
                                             <button onClick={() => navigator.clipboard.writeText(part.text || '')} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-800 rounded text-gray-400 hover:text-gray-600"><CopyIcon className="w-4 h-4"/></button>
                                         </div>
                                     )}
                                 </div>
                             ))}
                        </div>
                    </div>
                ))}
            </div>
        )}
      </div>

      {/* Floating Input Area */}
      <div className="absolute bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-white via-white to-transparent dark:from-gray-900 dark:via-gray-900 pt-10">
          <div className="max-w-3xl mx-auto">
              <div className="relative flex items-end gap-2 p-2 bg-white dark:bg-gray-800 rounded-[2rem] shadow-[0_0_20px_rgba(0,0,0,0.05)] border border-gray-200 dark:border-gray-700">
                   <input type="file" ref={fileInputRef} onChange={handleImageSelect} accept="image/*" className="hidden" />
                   <button onClick={() => fileInputRef.current?.click()} className="p-3 mb-0.5 rounded-full text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 hover:text-gray-600 transition-colors">
                       <ImageIcon className="w-6 h-6"/>
                   </button>
                   <textarea
                       ref={textareaRef}
                       value={input}
                       onChange={e => setInput(e.target.value)}
                       onKeyDown={e => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                       placeholder="Message Cognix..."
                       className="flex-1 bg-transparent border-none outline-none resize-none py-3.5 max-h-32 text-gray-900 dark:text-white placeholder-gray-400"
                       rows={1}
                   />
                   <button onClick={() => handleSendMessage()} disabled={isLoading || (!input && !selectedImage)} 
                       className={`p-2.5 mb-1 rounded-full text-white transition-all transform active:scale-95 disabled:opacity-50 disabled:scale-100
                           ${input || selectedImage ? 'bg-blue-600 hover:bg-blue-700 shadow-md' : 'bg-gray-300 dark:bg-gray-700'}
                       `}>
                       <SendIcon className="w-5 h-5"/>
                   </button>
              </div>
              <div className="text-center mt-3">
                  <p className="text-[11px] text-gray-400 dark:text-gray-500">Cognix AI, created by Shashwat Ranjan Jha.</p>
              </div>
          </div>
      </div>
    </div>
  );
};
